	["A totem item for each element, and an Ankh later."] = "Un objeto tótem para cada elemento, y más tarde un Anj.",
	["A totem that gives mana to your whole group. Use it when you run low."] = "Un tótem que da maná a todo tu grupo. Úsalo cuando te quedes corto.",
	["A trogg boss, with helpers."] = "Un jefe trogg, con ayudantes.",
	["A trogg boss, with two small helpers."] = "Un jefe trogg, con dos pequeños ayudantes.",
	["A troll city that sank into the sea off Stranglethorn Vale. We know only part of the route."] = "Una ciudad trol que se hundió en el mar frente a la Vega de Tuercespina. Solo conocemos parte de la ruta.",
	["A troll raid for 20 players in the jungle of Stranglethorn Vale. It ends with Hakkar."] = "Una banda trol para 20 jugadores en la jungla de la Vega de Tuercespina. Termina con Hakkar.",
	["A turtle that walks along the stream in the central cave, on the way to the bigger side."] = "Una tortuga que camina por el arroyo de la cueva central, de camino al lado más grande.",
	["A twisting cave of snakes, raptors and druids gone bad, with a short escort at the end. Eight bosses, for levels 15 to 24."] = "Una cueva retorcida de serpientes, raptores y druidas corrompidos, con una breve escolta al final. Ocho jefes, para niveles 15 a 24.",
	["A two-handed weapon and Seal of Command from level 20. Simple to play: you hit hard and can heal yourself between fights."] = "Un arma de dos manos y Sello de orden desde el nivel 20. Fácil de jugar: pegas fuerte y puedes sanarte entre combates.",
	["A vendor who repairs restores worn gear for a fee."] = "Un vendedor que repara restaura el equipo desgastado a cambio de dinero.",
	["A wrong point is not forever: your class trainer can reset your talents for a fee that starts at 1 gold and grows each time."] = "Un punto mal puesto no es para siempre: tu instructor de clase puede reiniciar tus talentos por un precio que empieza en 1 de oro y sube cada vez.",
	["Abandon"] = "Abandonar",
	["Abilities"] = "Facultades",
	["About %d minutes on foot"] = "Unos %d minutos a pie",
	["About a minute on foot"] = "Cerca de un minuto a pie",
	["About this place"] = "Sobre este lugar",
	["Action Bar 2"] = "Barra de acción 2",
	["Add"] = "Add",
	["Add Serpent Sting, then press Arcane Shot every time it is ready."] = "Aplica Aguijón de serpiente y luego pulsa Tiro Arcano cada vez que esté listo.",
	["Add Wrack to the enemy. It makes your other damage over time spells hurt more."] = "Aplica Arruinar al enemigo. Hace que tus otros hechizos de daño con el tiempo duelan más.",
	["Adventure"] = "Aventura",
	["Advice cards"] = "Tarjetas de consejos",
	["After Barthilas, near the end of the Undead part."] = "Después de Barthilas, cerca del final de la parte No-muerta.",
	["After Grox. His death opens the big gate behind him."] = "Después de Grox. Su muerte abre la gran puerta que tiene detrás.",
	["After a big hit on you, you heal yourself for a while."] = "Tras recibir un golpe fuerte, te sanas durante un rato.",
	["After a critical Holy Shock or Flash of Light, your next Holy Light casts faster."] = "Tras un Choque Sagrado o Destello de Luz crítico, tu siguiente Luz Sagrada se lanza más rápido.",
	["After a critical strike you swing faster for a few hits."] = "Tras un golpe crítico atacas más rápido durante unos golpes.",
	["After a critical strike, you deal more damage for a while."] = "Tras un golpe crítico, infliges más daño durante un rato.",
	["After a fight, cast Rejuvenation on yourself (and Regrowth from level 12), then move on."] = "Tras un combate, lánzate Rejuvenecimiento (y Recrecimiento desde el nivel 12) y sigue adelante.",
	["After a kill, your next attack is far more likely to crit."] = "Tras una muerte, tu siguiente ataque tiene muchas más probabilidades de ser crítico.",
	["After one visit Trailhead lists them here with prices."] = "Tras una visita, Trailhead los muestra aquí con sus precios.",
	["After that"] = "Después",
	["After the first boss."] = "Después del primer jefe.",
	["After the first bosses."] = "Después de los primeros jefes.",
	["After you are hit, you often deal more damage for a while."] = "Cuando te golpean, a menudo infliges más daño durante un rato.",
	["After you are hit, you sometimes block more for a while."] = "Cuando te golpean, a veces bloqueas más durante un rato.",
	["Aggro"] = "Agro",
	["Agility"] = "Agilidad",
	["Agility first, then Stamina and Intellect. Use the hardest-hitting bow, gun or crossbow you can find."] = "Primero Agilidad, luego Aguante e Intelecto. Usa el arco, arma de fuego o ballesta que más pegue.",
	["Agility first, then Stamina. Two one-handed weapons, and leather armor."] = "Primero Agilidad, luego Aguante. Dos armas de una mano y armadura de cuero.",
	["Alchemy"] = "Alquimia",
	["Alive"] = "Vivo",
	["Alive, with Resurrection Sickness"] = "Vivo, con Dolencia de resurrección",
	["All %d of your points are spent. You have had one for every level since %d, so the next comes at level %d."] = "Has gastado tus %d puntos. Has tenido uno por cada nivel desde el %d, así que el siguiente llega a nivel %d.",
	["All your Shadow damage goes up."] = "Todo tu daño de Sombras aumenta.",
	["All your Shadow spells do more damage and drain more life."] = "Todos tus hechizos de Sombras hacen más daño y drenan más vida.",
	["All your healing spells heal more."] = "Todos tus hechizos de sanación sanan más.",
	["All your talent points are spent."] = "Has gastado todos tus puntos de talento.",
	["All zones"] = "Todas las zonas",
	["Alliance players can enter, but it is a long, risky walk, and its quests are for the Horde."] = "Los jugadores de la Alianza pueden entrar, pero es un camino largo y arriesgado, y sus misiones son para la Horda.",
	["Almost"] = "Casi",
	["Along the main path, in his own room with no helpers."] = "En el camino principal, en su propia sala sin ayudantes.",
	["Amberstill Ranch, Dun Morogh"] = "Granja de Semperámbar, Dun Morogh",
	["Ammunition for your bow or gun, and food for your pet."] = "Munición para tu arco o arma de fuego, y comida para tu mascota.",
	["An arena: everyone fights"] = "Una arena: todos luchan",
	["An armored fighter with healing and blessings."] = "Un luchador con armadura que sana y da bendiciones.",
	["An enemy's attention. Tanks try to hold it."] = "La atención de un enemigo. Los tanques intentan mantenerla.",
	["An extra Frost hit to use while an enemy is chilled."] = "Un golpe de Escarcha extra para usar mientras un enemigo está helado.",
	["An extra enemy that joins a fight."] = "Un enemigo extra que se une a un combate.",
	["An instant heal for a friend who has your Rejuvenation or Regrowth on them."] = "Una sanación instantánea para un amigo que tenga tu Rejuvenecimiento o Recrecimiento.",
	["An instant heal for anyone who has your Rejuvenation or Regrowth on them."] = "Una sanación instantánea para cualquiera que tenga tu Rejuvenecimiento o Recrecimiento.",
	["An ogre fortress in Riverglades, run by the Twilight cult. The route winds up a hill. We know only part of it."] = "Una fortaleza ogra en Clarofluvial, dirigida por el culto Crepuscular. La ruta sube serpenteando una colina. Solo conocemos parte de ella.",
	["An old quilboar city of bone and thorn, with undead at its heart. Six bosses, for levels 37 to 46."] = "Una antigua ciudad jabaespín de hueso y espinas, con no-muertos en su corazón. Seis jefes, para niveles 37 a 46.",
	["And %d more."] = "Y %d más.",
	["Any cooking trainer teaches the campfire."] = "Cualquier instructor de cocina enseña la hoguera.",
	["Any monster or enemy creature."] = "Cualquier monstruo o criatura enemiga.",
	["Any vendor with an anvil sign can repair it for a few coins."] = "Cualquier vendedor con el símbolo del yunque puede repararlo por unas monedas.",
	["Appears after you buy Dark Iron Ale mugs and hand them to Private Rocknot."] = "Aparece tras comprar jarras de cerveza Hierro Negro y dárselas al soldado Rocknot.",
	["Appears in the Pit of Sacrifice after the Prophet dies. Guides say to pull it with Dreamscythe, one dragon at a time."] = "Aparece en el Pit of Sacrifice cuando muere el Profeta. Las guías dicen que lo atraigas junto con Guadañasueños, un dragón cada vez.",
	["Appears in the Pit of Sacrifice with Weaver."] = "Aparece en el Pit of Sacrifice con Sastrón.",
	["Appears in the flooded tomb when the last guardian dies."] = "Aparece en la tumba inundada cuando muere el último guardián.",
	["Appears only if you walk the Belnistrasz escort quest to its end."] = "Solo aparece si completas hasta el final la misión de escolta de Belnistrasz.",
	["Appears when Weaver and Dreamscythe are dead."] = "Aparece cuando Sastrón y Guadañasueños están muertos.",
	["Appears when the three beer kegs in the bar are smashed."] = "Aparece cuando se rompen los tres barriles de cerveza del bar.",
	["Appears with Hazzas."] = "Aparece con Hazzas.",
	["Arcane Shot is ready again sooner, so you press it more often."] = "Tiro Arcano vuelve a estar listo antes, así que lo pulsas más a menudo.",
	["Area of effect: hits many enemies at once."] = "Área de efecto: golpea a muchos enemigos a la vez.",
	["Armor"] = "Armadura",
	["Armory wing, levels 36 to 44. The Scarlet Key opens its door. The key is in the Library wing."] = "Ala de la Armería, niveles 36 a 44. La Llave Escarlata abre su puerta. La llave está en el ala de la Biblioteca.",
	["As of your last visit to the trainer."] = "Según tu última visita al instructor.",
	["Ask an innkeeper to make their inn your home."] = "Pide a un tabernero que haga de su posada tu hogar.",
	["Ask your group for the plan."] = "Pide el plan a tu grupo.",
	["Ask your raid leader for the plan before each boss."] = "Pide el plan a tu líder de banda antes de cada jefe.",
	["Ask your raid leader for the plan. Cure curses if you can."] = "Pide el plan a tu líder de banda. Cura maldiciones si puedes.",
	["Ask your raid leader for the plan. Players take control of him."] = "Pide el plan a tu líder de banda. Los jugadores toman el control de él.",
	["At full durability"] = "Durabilidad completa",
	["At level %d a class quest teaches %s, not the trainer."] = "A nivel %d, una misión de clase enseña %s, no el instructor.",
	["At level %d your trainer has %s for you, %s in all."] = "A nivel %d tu instructor tiene %s para ti, %s en total.",
	["At level %d: %d levels to go"] = "A nivel %d: faltan %d niveles",
	["At the Site of the Guardian. Click the panel by the right column to start."] = "En el Lugar del Guardián. Haz clic en el panel junto a la columna derecha para empezar.",
	["At the back of the Iron Hall."] = "Al fondo del Iron Hall.",
	["At the back of the Spider Wing."] = "Al fondo del ala Arácnida.",
	["At the big cannon in the Living part."] = "Junto al gran cañón de la parte Viva.",
	["At the bottom of the ramp, before the last boss."] = "Al pie de la rampa, antes del último jefe.",
	["At the door to the wizard's room."] = "En la puerta de la sala del mago.",
	["At the end of the Armory wing."] = "Al final del ala de la Armería.",
	["At the end of the Construct Wing."] = "Al final del ala de los Ensamblajes.",
	["At the end of the Library wing."] = "Al final del ala de la Biblioteca.",
	["At the end of the Plague Wing."] = "Al final del ala de la Peste.",
	["At the end of the orange side, in Poison Falls."] = "Al final del lado naranja, en Poison Falls.",
	["At the fireplace of the burned house. Five waves of undead come first."] = "En la chimenea de la casa quemada. Primero llegan cinco oleadas de no-muertos.",
	["At the lowest point of the hall loop."] = "En el punto más bajo del circuito de pasillos.",
	["At the start of the Undead part, in the crypts."] = "Al principio de la parte No-muerta, en las criptas.",
	["At the start, take the first side tunnel on the left. Blastmaster Emi Shortfuse waits at the end."] = "Al principio, toma el primer túnel lateral a la izquierda. La maestra de explosivos Emi Shortfuse espera al final.",
	["At the top of a staircase on the left path, in a room with a pool."] = "En lo alto de una escalera en el camino de la izquierda, en una sala con un estanque.",
	["At the top of the spiral ramp in Earth Song Falls."] = "En lo alto de la rampa en espiral de Earth Song Falls.",
	["At the very end of the dungeon, on the raised ledge."] = "Al final del todo de la mazmorra, en la cornisa elevada.",
	["At the west end of the Dark Iron Highway."] = "En el extremo oeste de la Dark Iron Highway.",
	["At two points in the fight it makes smaller stone helpers. Kill them."] = "Dos veces durante el combate crea pequeños ayudantes de piedra. Mátalos.",
	["At vendors"] = "En vendedores",
	["Auction"] = "Subasta",
	["Auction house"] = "Casa de subastas",
	["Back"] = "Atrás",
	["Bags"] = "Bolsas",
	["Bandages"] = "Vendas",
	["Bank"] = "Banco",
	["Barrow Deeps"] = "Barrow Deeps",
	["Bars and bags"] = "Barras y bolsas",
	["Bartering: cheaper prices at vendors"] = "Regateo: precios más baratos en vendedores",
	["Bash (level 14) stuns an enemy for a moment. Use it to stop a hard hit."] = "Azote (nivel 14) aturde a un enemigo un momento. Úsalo para parar un golpe fuerte.",
	["Bash stuns for longer and is ready again sooner."] = "Azote aturde más tiempo y vuelve a estar listo antes.",
	["Basic Campfire"] = "Hoguera básica",
	["Beat the three at the seal first. If he seems to die early, keep hitting him: he is faking."] = "Vence primero a los tres del sello. Si parece morir antes de tiempo, sigue golpeándolo: está fingiendo.",
	["Before the next fight"] = "Antes del próximo combate",
	["Behind the bar. Attacking him turns the whole bar hostile."] = "Detrás de la barra. Atacarle vuelve hostil a todo el bar.",
	["Behind the door that the gnome Weegli blasts open."] = "Tras la puerta que vuela el gnomo Weegli.",
	["Being hit is less likely to interrupt your Drain spells and Wrack."] = "Es menos probable que los golpes interrumpan tus hechizos de Drenar y Arruinar.",
	["Being hit is less likely to slow down your healing spells."] = "Es menos probable que los golpes frenen tus hechizos de sanación.",
	["Below the Spiral of Thorns, where he patrols."] = "Debajo de la Spiral of Thorns, por donde patrulla.",
	["Beside game windows"] = "Junto a las ventanas del juego",
	["Between fights"] = "Entre combates",
	["Between fights, sit down and drink so your Mana comes back."] = "Entre combates, siéntate y bebe para recuperar el maná.",
	["Beyond him, turn right and climb to a view of the city. The path splits."] = "Pasado él, gira a la derecha y sube hasta una vista de la ciudad. El camino se divide.",
	["Beyond the first boss."] = "Pasado el primer jefe.",
	["Bind on equip: yours alone once you put it on."] = "Se liga al equiparlo: solo tuyo en cuanto te lo pones.",
	["Bind on pickup: it is yours alone once you take it."] = "Se liga al recogerlo: es solo tuyo en cuanto lo coges.",
	["Blacksmithing"] = "Herrería",
	["Blessing of Protection is ready sooner, and Blessing of Freedom lasts longer."] = "Bendición de Protección está lista antes, y Bendición de Libertad dura más.",
	["Blocking, and being critically hit, sometimes gives you a free extra attack."] = "Bloquear, y recibir golpes críticos, a veces te da un ataque extra gratis.",
	["Bloodhoof Village, Mulgore"] = "Poblado Pezuña de Sangre, Mulgore",
	["Bloodrage gives you more Rage."] = "Sanguinario te da más Ira.",
	["Boats"] = "Barcos",
	["Boats and zeppelins cross the water. Ask a guard where to board."] = "Los barcos y zepelines cruzan el agua. Pregunta a un guardia dónde embarcar.",
	["Boats and zeppelins link the continents from the big cities and ports. Ask a city guard which one goes to %s."] = "Los barcos y zepelines unen los continentes desde las grandes ciudades y puertos. Pregunta a un guardia de la ciudad cuál va a %s.",
	["Bonus left"] = "Bonus restante",
	["Bountiful Harvest: more rare materials"] = "Cosecha generosa: más materiales raros",
	["Break her mind control."] = "Rompe su control mental.",
	["Break his mind control."] = "Rompe su control mental.",
	["Break mind control quickly."] = "Rompe el control mental rápido.",
	["Break people out of the webs fast."] = "Saca rápido a la gente de las telarañas.",
	["Break roots if you can. Stay out of the green pools."] = "Rompe los enraizamientos si puedes. No pises los charcos verdes.",
	["Brill, Tirisfal Glades"] = "Rémol, Claros de Tirisfal",
	["Bring a way to breathe underwater if you have one."] = "Lleva algo para respirar bajo el agua si tienes.",
	["Bring a way to cure disease and poison."] = "Lleva algo para curar enfermedades y venenos.",
	["Bring back"] = "Recuperar",
	["Bring back the advice you closed on the Home page."] = "Recupera los consejos que cerraste en la página Inicio.",
	["Bring fear protection."] = "Lleva protección contra el miedo.",
	["Bring fire and shadow resistance gear if you have some."] = "Lleva equipo de resistencia al fuego y a las Sombras si tienes.",
	["Bring fire resistance gear if your guild has some."] = "Lleva equipo de resistencia al fuego si tu hermandad tiene.",
	["Bring nature resistance gear."] = "Lleva equipo de resistencia a la naturaleza.",
	["Bring the key. The door is locked."] = "Lleva la llave. La puerta está cerrada.",
	["Buff"] = "Buff",
	["Build complete"] = "Build completa",
	["Builds"] = "Builds",
	["Builds are written from the game's own talent texts. Your class has none yet."] = "Las builds se escriben a partir de los textos de talentos del propio juego. Tu clase aún no tiene ninguna.",
	["Buy the abilities you use, sell what you do not need, and put the rest aside."] = "Compra las facultades que usas, vende lo que no necesitas y deja el resto aparte.",
	["By the game's own tables, at level %d your trainer should have %s."] = "Según las tablas del propio juego, a nivel %d tu instructor debería tener %s.",
	["Call Pet, put Hunter's Mark on the enemy, then shoot with Auto Shot."] = "Usa Llamar a mascota, pon Marca del cazador en el enemigo y dispara con Tiro automático.",
	["Called out by a mail quest in the Living part."] = "Aparece con una misión de correo en la parte Viva.",
	["Called out for a quest in the Living part."] = "Aparece por una misión en la parte Viva.",
	["Called out near Ras Frostwhisper with a quest item (a brazier)."] = "Aparece cerca de Ras Murmuhielo con un objeto de misión (un brasero).",
	["Called out on the patio with a quest item (Blood of Innocents)."] = "Aparece en el patio con un objeto de misión (Sangre de inocentes).",
	["Camera"] = "Cámara",
	["Camp Chair"] = "Silla de campamento",
	["Camp Tent"] = "Tienda de campamento",
	["Camp items"] = "Objetos de campamento",
	["Camping"] = "Acampada",
	["Camping is Forever's own system. A cook lights a campfire with Flint and Tinder and Simple Wood, and anyone who sits or crafts beside it for a minute gets the buffs of the camp items set up around it."] = "La acampada es un sistema propio de Forever. Un cocinero enciende una hoguera con Sílex y Yesca y Madera simple, y quien se siente o fabrique a su lado durante un minuto recibe los beneficios de los objetos de campamento que la rodean.",
	["Candles for group buffs later, and a feather for Levitate."] = "Velas para beneficios de grupo más adelante, y una pluma para Levitar.",
	["Cast Blessing of Wisdom (level 14) on party members who use Mana, and on yourself."] = "Lanza Bendición de Sabiduría (nivel 14) a los miembros del grupo que usen maná, y a ti mismo.",
	["Cast Corruption and Bane of Agony on the enemy, then Shadow Bolt until it falls."] = "Lanza Corrupción y Terror de agonía al enemigo, y luego Descarga de las Sombras hasta que caiga.",
	["Cast Healing Wave on whoever has the lowest health bar. Heal early."] = "Lanza Onda de curación a quien tenga la barra de salud más baja. Sana pronto.",
	["Cast Ice Barrier on yourself before a hard fight."] = "Lánzate Barrera de hielo antes de un combate difícil.",
	["Cast Mark of the Wild on everyone before the first fight."] = "Lanza Marca de lo salvaje a todos antes del primer combate.",
	["Cast Seal of Righteousness before the fight, then hit the enemy with your weapon."] = "Lanza Sello de rectitud antes del combate y luego golpea al enemigo con tu arma.",
	["Casts damaging spells and calls demons to help."] = "Lanza hechizos de daño e invoca demonios que le ayudan.",
	["Casts strong spells from a distance. Makes food and water."] = "Lanza hechizos potentes a distancia. Crea comida y agua.",
	["Cat Form (level 20): Claw, or Shred from behind, builds points. Ferocious Bite (level 24) spends them."] = "Forma felina (nivel 20): Zarpa, o Triturar por la espalda, acumula puntos. Mordedura feroz (nivel 24) los gasta.",
	["Cathedral wing, levels 38 to 46, the strongest. It also needs the Scarlet Key to reach its portal."] = "Ala de la Catedral, niveles 38 a 46, la más fuerte. También necesita la Llave Escarlata para llegar a su portal.",
	["Challenges you finish earn them. Your whole account shares them."] = "Los consigues al completar desafíos. Toda tu cuenta los comparte.",
	["Change into Bear Form, then use Maul and Growl to keep the enemy on you."] = "Cambia a Forma de oso y usa Machaque y Bramido para mantener al enemigo sobre ti.",
	["Change into Bear Form. Start each fight with Growl, so the enemy attacks you."] = "Cambia a Forma de oso. Empieza cada combate con Bramido para que el enemigo te ataque a ti.",
	["Changes shape: bear to take hits, cat to fight, or heals."] = "Cambia de forma: oso para aguantar golpes, gato para luchar, o sanaciones.",
	["Changing form costs less Mana, so you can change often."] = "Cambiar de forma cuesta menos maná, así que puedes cambiar a menudo.",
	["Changing form costs less Mana."] = "Cambiar de forma cuesta menos maná.",
	["Changing into Bear Form can give you Rage to start a fight with."] = "Cambiar a Forma de oso puede darte Ira para empezar un combate.",
	["Character"] = "Personaje",
	["Character window, then the Reputation tab"] = "Ventana de personaje, luego la pestaña Reputación",
	["Charcoal and orange, sharp and bold"] = "Carbón y naranja, nítido y llamativo",
	["Charge gives more Rage, so every fight starts with a hit ready."] = "Embestir da más Ira, así que cada combate empieza con un golpe listo.",
	["Charge in, put Rend on the enemy, then spend Rage on Heroic Strike."] = "Usa Embestir, pon Desgarrar en el enemigo y gasta la Ira en Golpe heroico.",
	["Chat channels"] = "Canales de chat",
	["Chat commands"] = "Comandos de chat",
	["Check complete"] = "Comprobación completa",
	["Chest"] = "Pecho",
	["Chill effects last longer and slow enemies more, so they reach you later."] = "Los efectos de escalofrío duran más y ralentizan más a los enemigos, así que tardan más en alcanzarte.",
	["Choose which key does what. Trailhead does not change keys."] = "Elige qué tecla hace qué. Trailhead no cambia teclas.",
	["Class"] = "Clase",
	["Class quest: %s"] = "Misión de clase: %s",
	["Class trainer"] = "Instructor de clase",
	["Class trainers teach new spells and new ranks of old ones. Visit yours every couple of levels."] = "Los instructores de clase enseñan hechizos nuevos y nuevos rangos de los antiguos. Visita el tuyo cada par de niveles.",
	["Classic or Enhanced: two ready-made sets of settings for how the game looks and plays. Read the buttons there before you pick."] = "Clásico o Mejorado: dos conjuntos de ajustes ya preparados para cómo se ve y se juega el juego. Lee los botones antes de elegir.",
	["Claw, Rake, Shred, Maul and Swipe hit harder, and it opens Lacerate."] = "Zarpa, Arañazo, Triturar, Machaque y Flagelo pegan más fuerte, y abre Lacerar.",
	["Cleanse and Purify cost less Mana, and Exorcism and Holy Wrath are ready sooner."] = "Purgación y Purificar cuestan menos maná, y Exorcismo y Cólera sagrada están listos antes.",
	["Clear every guard before you pull a boss. They join the fight."] = "Limpia todos los guardias antes de atraer a un jefe. Se unen al combate.",
	["Clear his helpers before you start on him. The tank holds them while others kill them."] = "Limpia sus ayudantes antes de empezar con él. El tanque los retiene mientras los demás los matan.",
	["Clear the area first. Interrupt her spells and kill her totems."] = "Limpia la zona primero. Interrumpe sus hechizos y mata sus tótems.",
	["Clear the dragonkin first or they join the fight. He puts the highest threat target to sleep."] = "Limpia primero a los dragonantes o se unirán al combate. Duerme al objetivo con más amenaza.",
	["Clear the goblins around him first, then pull him on his own."] = "Limpia primero a los goblins que lo rodean y luego atráelo solo.",
	["Clear the goblins in the room first. When the machine dies, Sneed jumps out and can disarm someone."] = "Limpia primero a los goblins de la sala. Cuando la máquina muere, Sneed salta fuera y puede desarmar a alguien.",
	["Clear the guards first. His veil cuts the healing you get, so interrupt it."] = "Limpia primero a los guardias. Su velo reduce la sanación que recibes, así que interrúmpelo.",
	["Clear the guards first. Interrupt his fear."] = "Limpia primero a los guardias. Interrumpe su miedo.",
	["Clear the murlocs in his room first, then pull him alone. His net lowers threat."] = "Limpia primero a los múrlocs de su sala y luego atráelo solo. Su red reduce la amenaza.",
	["Clear the room first. His fear scatters the group and pulls the rest."] = "Limpia primero la sala. Su miedo dispersa al grupo y atrae al resto.",
	["Clear the whole hold first. He drains mana."] = "Limpia primero toda la bodega. Drena maná.",
	["Clear the whole room before you pull."] = "Limpia toda la sala antes de atraer.",
	["Click a player's name in chat to whisper them. Shift-click an item to put it in a chat message."] = "Haz clic en el nombre de un jugador en el chat para susurrarle. Mayús-clic en un objeto lo pone en un mensaje de chat.",
	["Click the shrines in the right order or you get cursed. Do not jump into the pit."] = "Haz clic en los santuarios en el orden correcto o te maldecirán. No saltes al foso.",
	["Click: open or close\nRight-click: settings\nDrag: move this button"] = "Clic: abrir o cerrar\nClic derecho: ajustes\nArrastrar: mover este botón",
	["Climb out of the sewers into the streets of Dalaran."] = "Sal de las cloacas a las calles de Dalaran.",
	["Close the window when a fight starts and bring it back afterwards."] = "Cierra la ventana cuando empiece un combate y vuelve a abrirla después.",
	["Cloth armor and bags, from cloth enemies drop. Needs no gatherer."] = "Armaduras de tela y bolsas, con la tela que sueltan los enemigos. No necesita recolector.",
	["Colours"] = "Colores",
	["Comes out of the pool when someone hits the gong with the Mallet of Zul'Farrak."] = "Sale del estanque cuando alguien golpea el gong con el Mazo de Zul'Farrak.",
	["Comes with the last wave of the stairs event."] = "Llega con la última oleada del evento de las escaleras.",
	["Coming up"] = "Próximamente",
	["Commands:"] = "Comandos:",
	["Condition"] = "Estado",
	["Cone of Cold, an area blast in front of you, hits harder."] = "Cono de frío, una explosión de área delante de ti, pega más fuerte.",
	["Consecration, Exorcism and Holy Wrath cost less Mana."] = "Consagración, Exorcismo y Cólera sagrada cuestan menos maná.",
	["Contested: both sides meet here"] = "En disputa: ambas facciones se encuentran aquí",
	["Cooking"] = "Cocina",
	["Corruption casts faster and hurts more."] = "Corrupción se lanza más rápido y duele más.",
	["Cost: about %s."] = "Coste: unos %s.",
	["Crafting"] = "Fabricación",
	["Critical strikes give you extra Rage, so you can use your attacks more."] = "Los golpes críticos te dan Ira extra, así que puedes usar más tus ataques.",
	["Cross the bridge to the north."] = "Cruza el puente hacia el norte.",
	["Cross the courtyard and go in through the doors to the twisting halls of the main keep."] = "Cruza el patio y entra por las puertas a los pasillos retorcidos del torreón principal.",
	["Cross the marsh to Stalker's Thicket, a field of tall grass full of raptors."] = "Cruza el marjal hasta la Fronda del Acechador, un campo de hierba alta lleno de raptores.",
	["Cross the sea to %s"] = "Cruza el mar hasta %s",
	["Crowd control the helpers and kill him first."] = "Controla a los ayudantes y mátalo a él primero.",
	["Crowd control: keeps an enemy from fighting for a while."] = "Control de masas: impide que un enemigo luche durante un rato.",
	["Crypts under the tower of Karazhan, carried over from an earlier season. We only know the boss list, not the route."] = "Criptas bajo la torre de Karazhan, de una temporada anterior. Solo conocemos la lista de jefes, no la ruta.",
	["Cultists cast spells that hurt. Pull one group at a time."] = "Los sectarios lanzan hechizos que duelen. Atrae un grupo cada vez.",
	["Cure his curse on the group."] = "Cura su maldición del grupo.",
	["Cure the disease called Ghoul Plague at once. It slows you."] = "Cura en cuanto puedas la enfermedad llamada Peste necrófaga. Te ralentiza.",
	["Cure whatever he casts on the group."] = "Cura lo que lance sobre el grupo.",
	["Damage"] = "Daño",
	["Damage over time and a Voidwalker to hold the enemy. You start a fight, then watch it fall. Slow and safe, with little to learn."] = "Daño con el tiempo y un abisario para retener al enemigo. Empiezas un combate y ves cómo cae. Lento y seguro, con poco que aprender.",
	["Damage per second. A player who deals damage."] = "Daño por segundo. Un jugador que inflige daño.",
	["Danger and PvP"] = "Peligro y JcJ",
	["Darnassus"] = "Darnassus",
	["Date unknown"] = "Fecha desconocida",
	["Debuff"] = "Debuff",
	["Dedicated Study: raises your lowest profession"] = "Estudio dedicado: sube tu profesión más baja",
	["Deep in the temple, after the dragon fights. No ritual or quest is needed."] = "En lo profundo del templo, tras los combates con dragones. No hace falta ritual ni misión.",
	["Deep inside Blackrock Depths, past the lava lake. Reach it through the Blackrock Mountain entrance in the Burning Steppes or Searing Gorge."] = "En lo profundo de las Profundidades de Roca Negra, pasado el lago de lava. Se llega por la entrada de la Montaña Roca Negra en Las Estepas Ardientes o La Garganta de Fuego.",
	["Deeper in the Graveyard wing, near the end."] = "Más adentro del ala del Cementerio, cerca del final.",
	["Deeper in the Undead part."] = "Más adentro en la parte No-muerta.",
	["Deeper in the city. Exact place is not known."] = "Más adentro en la ciudad. No se conoce el lugar exacto.",
	["Defeat a boss in a dungeon with a group"] = "Derrota a un jefe en una mazmorra con un grupo",
	["Demon Armor protects you better."] = "Armadura demoníaca te protege mejor.",
	["Did you know?"] = "¿Sabías que...?",
	["Diplomat: reputation grows faster"] = "Diplomático: la reputación sube más rápido",
	["Dire Maul is a ruined elf city in Feralas with three parts: East, West and North, all for level 55 and up. All three are in this one dungeon."] = "La Masacre es una ciudad élfica en ruinas en Feralas con tres partes: Este, Oeste y Norte, todas para nivel 55 y más. Las tres están en esta misma mazmorra.",
	["Dive into the pool beside the staircase to reach the flooded tomb."] = "Lánzate al estanque junto a la escalera para llegar a la tumba inundada.",
	["Divine Favor makes your next heal a critical heal. Save it for an emergency."] = "Favor divino hace que tu siguiente sanación sea crítica. Guárdalo para una emergencia.",
	["Divine Shield and Divine Protection are ready sooner, and Forbearance wears off faster."] = "Escudo divino y Protección divina están listos antes, y Paciencia desaparece más rápido.",
	["Do East first. It has the key for the others."] = "Haz primero el Este. Tiene la llave para las demás.",
	["Do not chain-pull. Wait for the ogre patrols to pass."] = "No atraigas en cadena. Espera a que pasen las patrullas de ogros.",
	["Do not clump when he sprays."] = "No os agrupéis cuando rocía.",
	["Do not fight him in a doorway."] = "No luches contra él en una puerta.",
	["Do not hit the friendly drinkers."] = "No ataques a los bebedores amistosos.",
	["Do not jump or fall down. Monsters on lower paths run up to you."] = "No saltes ni te caigas. Los monstruos de los caminos de abajo suben corriendo a por ti.",
	["Do not kill them at the same time as each other."] = "No los mates al mismo tiempo.",
	["Do not stand in damage on the ground. Move out of it."] = "No te quedes en el daño del suelo. Sal de él.",
	["Do not stand in front of him."] = "No te pongas delante de él.",
	["Do not stand in his cone."] = "No te quedes en su cono.",
	["Do not stand in his fire."] = "No te quedes en su fuego.",
	["Do not stand near the player who burns."] = "No te acerques al jugador que arde.",
	["Do not stand near the tank when he casts his fire spell."] = "No te acerques al tanque cuando lanza su hechizo de fuego.",
	["Do not stay in his sight."] = "No te quedes en su línea de visión.",
	["Do not tank near the edge. He knocks you back."] = "No tanquees cerca del borde. Te empuja hacia atrás.",
	["Do not wander off. The city is huge and easy to get lost in."] = "No te alejes. La ciudad es enorme y es fácil perderse.",
	["Do the attunement quest before raid night."] = "Haz la misión de armonización antes de la noche de banda.",
	["Do the quests first. Reports say they give the key."] = "Haz primero las misiones. Dicen que dan la llave.",
	["Done"] = "Hecho",
	["Down"] = "Caído",
	["Draft"] = "Borrador",
	["Draft: every point is checked against the game's talent data, but we have not played this build through yet."] = "Borrador: cada punto se comprueba con los datos de talentos del juego, pero aún no hemos jugado esta build entera.",
	["Drag each one from your spellbook to an empty bar slot."] = "Arrastra cada uno desde tu libro de hechizos a una casilla vacía de la barra.",
	["Drag the title bar to move the window. This puts it back in the middle."] = "Arrastra la barra de título para mover la ventana. Esto la devuelve al centro.",
	["Drag them from your spellbook to a bar."] = "Arrástralos desde tu libro de hechizos a una barra.",
	["Dragon"] = "Dragón",
	["Drain Life and Wrack hurt more for each other Affliction effect on the target."] = "Drenar vida y Arruinar duelen más por cada otro efecto de Aflicción en el objetivo.",
	["Drain Soul drains the enemy while you hold it. If the enemy dies from it, you get a Soul Shard."] = "Drenar alma drena al enemigo mientras lo mantienes. Si el enemigo muere por él, obtienes un fragmento de alma.",
	["Drop a quest from your quest log. You can take it again."] = "Abandona una misión desde tu registro. Puedes volver a aceptarla.",
	["Dungeon"] = "Mazmorra",
	["Dungeon for a group of five"] = "Mazmorra para un grupo de cinco",
	["Dungeon healer"] = "Sanador de mazmorra",
	["Dungeon tank"] = "Tanque de mazmorra",
	["Dungeon, levels %d to %d"] = "Mazmorra, niveles %d a %d",
	["Dungeon: %s"] = "Mazmorra: %s",
	["Dungeons"] = "Mazmorras",
	["Dungeons and the levels they are meant for. You are level %d."] = "Las mazmorras y los niveles para los que están pensadas. Eres nivel %d.",
	["Dungeons need a group of five and you travel to the entrance yourselves."] = "Las mazmorras requieren un grupo de cinco y tenéis que viajar vosotros mismos hasta la entrada.",
	["Dungeons need a group of five."] = "Las mazmorras requieren un grupo de cinco.",
	["Dying"] = "Morir",
	["Each PvP season has a journey with weekly tasks. They give Honor and Rank Points, and three of them in a season also give a Legacy Point."] = "Cada temporada JcJ tiene un recorrido con tareas semanales. Dan honor y puntos de rango, y tres de ellas por temporada también dan un punto de legado.",
	["Each Shadow spell makes the enemy take more Shadow damage from you."] = "Cada hechizo de Sombras hace que el enemigo reciba más daño de Sombras de ti.",
	["Each bag slot next to your backpack takes one more bag. Monsters drop them, tailors make them, and the auction house sells them."] = "Cada casilla de bolsa junto a tu mochila admite una bolsa más. Los monstruos las sueltan, los sastres las fabrican y la casa de subastas las vende.",
	["Each gong ring brings spiders from both sides. The third ring calls the boss."] = "Cada toque del gong trae arañas por ambos lados. El tercer toque llama al jefe.",
	["Each raid resets once a week"] = "Cada banda se reinicia una vez por semana",
	["Each raid resets once a week."] = "Cada banda se reinicia una vez por semana.",
	["Each tick of Mind Flay hits harder than the one before it."] = "Cada tic de Despelleje mental pega más fuerte que el anterior.",
	["Each week"] = "Cada semana",
	["Each wing is a separate part. You can try them in any order."] = "Cada ala es una parte aparte. Puedes intentarlas en cualquier orden.",
	["Early in the stronghold. Exact place is not known."] = "Al principio de la fortaleza. No se conoce el lugar exacto.",
	["Early on, finish quests, sell grey items, and spend only on abilities and food. Put the rest aside for riding."] = "Al principio, completa misiones, vende los objetos grises y gasta solo en facultades y comida. Guarda el resto para la equitación.",
	["Early reports say the quests are for the Alliance. We have not confirmed it."] = "Los primeros informes dicen que las misiones son para la Alianza. No lo hemos confirmado.",
	["Earthcaller Halmgar is a rare boss on a plateau after Ramtusk. He does not always show up and is not needed."] = "Earthcaller Halmgar es un jefe raro en una meseta después de Colmicarnero. No siempre aparece y no es necesario.",
	["East part first, the Warpwood Quarter. It has no key door. The game lists its bosses in the order below."] = "Primero la parte Este, el Barrio Alabeo. No tiene puerta con llave. El juego lista sus jefes en el orden de abajo.",
	["Eastvale Logging Camp, Elwynn Forest"] = "Aserradero de la Vega del Este, Bosque de Elwynn",
	["Easy levelling"] = "Subir de nivel fácil",
	["Easy to beat."] = "Fácil de vencer.",
	["Easy to pull by accident, and that often ends in a wipe. Stop and get ready first."] = "Fácil de atraer sin querer, y eso suele acabar en wipe. Para y prepárate primero.",
	["Eat and drink to full. It is far faster than waiting."] = "Come y bebe hasta llenarte. Es mucho más rápido que esperar.",
	["Eat or drink before your next fight: it brings you back far faster than waiting."] = "Come o bebe antes del próximo combate: te recupera mucho más rápido que esperar.",
	["Edit Mode"] = "Modo edición",
	["Elite monsters walk the tunnel outside. Go in as a group."] = "Monstruos élite recorren el túnel de fuera. Entrad en grupo.",
	["Elite, group"] = "Élite, grupo",
	["Elite, rare"] = "Élite, raro",
	["Ember"] = "Ascua",
	["Empty slots"] = "Casillas vacías",
	["Enchanted Lute"] = "Laúd encantado",
	["Enchanting"] = "Encantamiento",
	["Enchants gear with what you break down. Needs no gatherer."] = "Encanta equipo con lo que desencantas. No necesita recolector.",
	["Enemies that crit you take some of the pain themselves."] = "Los enemigos que te hacen un crítico reciben parte del dolor.",
	["Enemies you kill return after a while, so do not linger."] = "Los enemigos que matas vuelven al rato, así que no te entretengas.",
	["Enemy at your feet? Frost Nova freezes it. Back away before you cast, as damage can break the freeze."] = "¿Un enemigo a tus pies? Nova de Escarcha lo congela. Aléjate antes de lanzar, porque el daño puede romper la congelación.",
	["Energy, which refills fast, and combo points."] = "Energía, que se recarga rápido, y puntos de combo.",
	["Engineering"] = "Ingeniería",
	["Enter and go up to the patio where the first boss is summoned. The game lists the bosses in the order below; groups may vary it."] = "Entra y sube al patio donde se invoca al primer jefe. El juego lista los jefes en el orden de abajo; los grupos pueden cambiarlo.",
	["Enter the furbolg tunnel in northern Azshara. The portal is deep inside it."] = "Entra en el túnel de los fúrbolgs en el norte de Azshara. El portal está en lo profundo.",
	["Entrance in %s"] = "Entrada en %s",
	["Evasion and Sprint are ready far more often."] = "Evasión y Correr están listos mucho más a menudo.",
	["Every boss is down. Well done!"] = "Todos los jefes han caído. ¡Bien hecho!",
	["Every character you play with Trailhead, saved each time you log out."] = "Cada personaje con el que juegas con Trailhead, guardado cada vez que cierras sesión.",
	["Every class spell you know is on a bar. Nothing to do here."] = "Todos los hechizos de clase que conoces están en una barra. Nada que hacer aquí.",
	["Every enemy shows a level. The colour of its name tells you how a fight against it will go. Players of the other side can also be a danger."] = "Cada enemigo muestra un nivel. El color de su nombre te dice cómo irá un combate contra él. Los jugadores del otro bando también pueden ser un peligro.",
	["Every kind of weapon has its own skill. It rises as you fight with that kind of weapon, up to a limit of 5 for each level you have. Every point under the limit takes a little off your chance to hit and to crit."] = "Cada tipo de arma tiene su propia habilidad. Sube al luchar con ese tipo de arma, hasta un límite de 5 por cada nivel que tengas. Cada punto por debajo del límite resta un poco a tu probabilidad de golpe y de crítico.",
	["Every point in this build is placed."] = "Todos los puntos de esta build están colocados.",
	["Every trainer, vendor and mailbox you use is remembered. Find it again from the Find it tab."] = "Se recuerda cada instructor, vendedor y buzón que usas. Encuéntralo de nuevo en la pestaña Buscar.",
	["Everything Trailhead knows about this"] = "Todo lo que Trailhead sabe de esto",
	["Everything is at full durability"] = "Todo está con durabilidad completa",
	["Everything you wear is at full durability. Nothing to repair."] = "Todo lo que llevas está con durabilidad completa. Nada que reparar.",
	["Eviscerate costs much less Energy."] = "Eviscerar cuesta mucha menos Energía.",
	["Eviscerate, your finishing move, hits harder."] = "Eviscerar, tu remate, pega más fuerte.",
	["Exalted"] = "Exaltado",
	["Execute (level 24) finishes an enemy that has 20% Health or less."] = "Ejecutar (nivel 24) remata a un enemigo con un 20% de Salud o menos.",
	["Execute costs less Rage."] = "Ejecutar cuesta menos Ira.",
	["Extra vendor buttons"] = "Botones extra en vendedores",
	["Faction Banner"] = "Estandarte de facción",
	["Falling into the central pit hurts a lot. Use the stairs."] = "Caer al foso central duele mucho. Usa las escaleras.",
	["Far above you. It will kill you, so walk around it."] = "Muy por encima de ti. Te matará, así que rodéalo.",
	["Faster attacks that also hit a second enemy."] = "Ataques más rápidos que además golpean a un segundo enemigo.",
	["Feed Pet works out of combat. Its happiness icon shows its food."] = "Alimentar mascota funciona fuera de combate. Su icono de felicidad muestra su comida.",
	["Feed your pet before a long fight. Before you tame a new one, leave your current pet with a stable master."] = "Alimenta a tu mascota antes de un combate largo. Antes de domesticar otra, deja la actual con un maestro de establos.",
	["Feeding"] = "Alimentar",
	["Feet"] = "Pies",
	["Fewer of your attacks are dodged or parried."] = "Menos de tus ataques son esquivados o parados.",
	["Field Guide: camp features come back sooner"] = "Guía de campo: las funciones del campamento vuelven antes",
	["Field Medicine: shorter bandage wait"] = "Medicina de campo: menos espera entre vendas",
	["Fight him in a corner."] = "Lucha contra él en una esquina.",
	["Fight him inside the pool so his knockback hurts less."] = "Lucha contra él dentro del estanque para que su derribo duela menos.",
	["Fight in Bear Form and keep enemies on you while your group hits them. You take a lot of damage and have the armor for it."] = "Lucha en Forma de oso y mantén a los enemigos sobre ti mientras tu grupo los golpea. Recibes mucho daño y tienes la armadura para ello.",
	["Fight in Bear Form to start, then Cat Form from level 20. You take hits well and can heal yourself between fights."] = "Empieza luchando en Forma de oso y luego en Forma felina desde el nivel 20. Aguantas bien los golpes y puedes sanarte entre combates.",
	["Fight up close with weapon hits, backed by Lightning Shield. Stormstrike at level 25 and a steady supply of Mana make the fights easy to follow."] = "Lucha cuerpo a cuerpo con golpes de arma, apoyado por Escudo de relámpagos. Golpe de tormenta a nivel 25 y un suministro constante de maná hacen que los combates sean fáciles de seguir.",
	["Fight with a shield. Seal of Fury (level 10) gives you a small shield with each hit."] = "Lucha con escudo. Sello de furia (nivel 10) te da un pequeño escudo con cada golpe.",
	["Fighting"] = "Combate",
	["Fights"] = "Combates",
	["Fill your mana before the wave fights."] = "Llena tu maná antes de los combates por oleadas.",
	["Find"] = "Buscar",
	["Find a flight master"] = "Busca un maestro de vuelo",
	["Find a group"] = "Busca un grupo",
	["Find a profession trainer"] = "Busca un instructor de profesión",
	["Find a stable master"] = "Busca un maestro de establos",
	["Find a trainer, vendor, bank or inn"] = "Busca un instructor, vendedor, banco o posada",
	["Find a vendor"] = "Busca un vendedor",
	["Find a weapon master"] = "Busca un maestro de armas",
	["Find an inn"] = "Busca una posada",
	["Find anything: trainer, bank, a zone, a dungeon..."] = "Busca lo que sea: instructor, banco, una zona, una mazmorra...",
	["Find it"] = "Buscar",
	["Find my trainer"] = "Buscar mi instructor",
	["Find nearby"] = "Buscar cerca",
	["Find repair"] = "Buscar reparación",
	["Find the auction house"] = "Busca la casa de subastas",
	["Find the riding trainer"] = "Busca el instructor de equitación",
	["Find trainer"] = "Buscar instructor",
	["Find your trainer"] = "Busca tu instructor",
	["Finding the door"] = "Encontrar la puerta",
	["Finger"] = "Dedo",
	["Finish Legacy Challenges. Each one is worth one point, shared by every character on your account. There are 65 at launch: Classes 27, Professions 18, PvP 12, Dungeons 3, Raids 3, Adventure 2."] = "Completa desafíos de legado. Cada uno vale un punto, compartido por todos los personajes de tu cuenta. Hay 65 en el lanzamiento: Clases 27, Profesiones 18, JcJ 12, Mazmorras 3, Bandas 3, Aventura 2.",
	["Finishing moves often give a combo point back."] = "Los remates suelen devolverte un punto de combo.",
	["Fire Blast is a quick extra hit. Use it to finish an enemy that is nearly dead."] = "Explosión de Fuego es un golpe extra rápido. Úsalo para rematar a un enemigo casi muerto.",
	["First Aid"] = "Primeros auxilios",
	["First Aid Kit"] = "Equipo de primeros auxilios",
	["First boss of the orange side, in a poison cave."] = "Primer jefe del lado naranja, en una cueva de veneno.",
	["First boss of the purple side, on the upper level."] = "Primer jefe del lado morado, en el nivel superior.",
	["First steps"] = "Primeros pasos",
	["Fish Bowl"] = "Cuenco con pescado",
	["Fishing"] = "Pesca",
	["Flash Heal on a friend also heals you."] = "Destello curativo sobre un amigo también te sana a ti.",
	["Flash of Light and Holy Light are less likely to be slowed when you are hit."] = "Es menos probable que Destello de Luz y Luz Sagrada se frenen cuando te golpean.",
	["Flight"] = "Vuelo",
	["Flight master"] = "Maestro de vuelo",
	["Flight masters connect the towns you have already visited."] = "Los maestros de vuelo conectan las ciudades que ya has visitado.",
	["Flight point: %s"] = "Punto de vuelo: %s",
	["Flight points for your side, nearest first"] = "Puntos de vuelo de tu bando, el más cercano primero",
	["Fly to %s"] = "Vuela a %s",
	["Fly to flight masters you have met before, for a small fee."] = "Vuela hasta maestros de vuelo que ya conoces, por un pequeño precio.",
	["Follow the cave tunnel back up into the main hall."] = "Sigue el túnel de la cueva de vuelta a la sala principal.",
	["Follow the marker to %s"] = "Sigue el marcador hasta %s",
	["Follow the paths down to Earth Song Falls, the waterfall cave at the bottom."] = "Sigue los caminos hasta Earth Song Falls, la cueva de la cascada del fondo.",
	["Follow the tunnel down to the cave with the pool and step into the way in. You arrive in a big central cave."] = "Sigue el túnel hasta la cueva con el estanque y entra por la entrada. Llegas a una gran cueva central.",
	["Follow the tunnel into a huge cave with wooden docks. Cross the docks to the pirate ship."] = "Sigue el túnel hasta una cueva enorme con muelles de madera. Cruza los muelles hasta el barco pirata.",
	["Follow this build"] = "Seguir esta build",
	["Following"] = "Siguiendo",
	["Food and drink"] = "Comida y bebida",
	["Food, drink, bandages and what your abilities use up."] = "Comida, bebida, vendas y lo que gastan tus facultades.",
	["For Great Honor: more honor"] = "Por gran honor: más honor",
	["For my level"] = "Para mi nivel",
	["For one player"] = "Para un jugador",
	["Forever's own progress for your whole account. Earn points, spend them on perks."] = "El progreso propio de Forever para toda tu cuenta. Gana puntos y gástalos en ventajas.",
	["Forever's systems"] = "Sistemas de Forever",
	["Forget"] = "Olvidar",
	["Forget all"] = "Olvidar todo",
	["Found places"] = "Lugares hallados",
	["Four wings behind one door: Graveyard, Library, Armory and Cathedral, each for higher levels (30 to 46 in all). Seven bosses in all."] = "Cuatro alas tras una misma puerta: Cementerio, Biblioteca, Armería y Catedral, cada una para niveles más altos (de 30 a 46 en total). Siete jefes en total.",
	["Frequent Flier: cheaper, faster flights"] = "Viajero frecuente: vuelos más baratos y rápidos",
	["Friendly"] = "Amistoso",
	["Friends help"] = "Los amigos ayudan",
	["From level %d you can learn to ride. Your own race's riding trainer teaches it for %s, with a mount vendor beside them, and a mount makes you %d%% faster. At level %d a second lesson for %s makes that %d%%. Prices are as reported at launch."] = "Desde el nivel %d puedes aprender a montar. El instructor de equitación de tu raza te enseña por %s, con un vendedor de monturas a su lado, y una montura te hace un %d%% más rápido. A nivel %d, una segunda lección por %s lo sube al %d%%. Precios según lo informado en el lanzamiento.",
	["From level %d. See the Mount topic."] = "Desde el nivel %d. Mira el tema Montura.",
	["From level 40 the trainer also offers a second set of talents to switch between."] = "Desde el nivel 40, el instructor también ofrece un segundo juego de talentos para alternar.",
	["From the built-in list"] = "De la lista integrada",
	["From the cave, climb a hill toward the main ruins. Light enemies come first."] = "Desde la cueva, sube una colina hacia las ruinas principales. Primero vienen enemigos débiles.",
	["From the dig site, go south through spiders to the Site of the Guardian."] = "Desde la excavación, ve al sur entre arañas hasta el Lugar del Guardián.",
	["From the entrance slope, walk into the Lost Marsh."] = "Desde la rampa de entrada, entra en el Marjal Perdido.",
	["From the entrance, clear the ghosts and take the west corridor."] = "Desde la entrada, limpia los fantasmas y toma el pasillo oeste.",
	["From the entrance, follow the tunnels. The path is mostly one way."] = "Desde la entrada, sigue los túneles. El camino es casi siempre de un solo sentido.",
	["From the entrance, head into the city and take the left-hand paths first."] = "Desde la entrada, ve hacia la ciudad y toma primero los caminos de la izquierda.",
	["From the game's flight map"] = "Del mapa de vuelo del juego",
	["From your class trainer"] = "De tu instructor de clase",
	["Frost Nova is ready again sooner, so you can freeze enemies in place more often."] = "Nova de Escarcha vuelve a estar lista antes, así que puedes congelar enemigos más a menudo.",
	["Frost damage slows him."] = "El daño de Escarcha lo ralentiza.",
	["Frost spells cost less mana, so you can cast more before you drink."] = "Los hechizos de Escarcha cuestan menos maná, así que puedes lanzar más antes de beber.",
	["Frostbolt from range, with ice to slow enemies and Ice Barrier at level 40 to soak hits. A few Arcane talents at the end save mana."] = "Descarga de Escarcha a distancia, con hielo para ralentizar enemigos y Barrera de hielo a nivel 40 para absorber golpes. Unos pocos talentos Arcanos al final ahorran maná.",
	["Frostbolt, your main spell, takes less time to cast."] = "Descarga de Escarcha, tu hechizo principal, tarda menos en lanzarse.",
	["Further along the main path of the bigger side."] = "Más adelante por el camino principal del lado grande.",
	["Further along the orange side."] = "Más adelante por el lado naranja.",
	["Further in, in the egg room."] = "Más adentro, en la sala de los huevos.",
	["Further in, in the glowing, dirty part of the old city."] = "Más adentro, en la parte brillante y sucia de la vieja ciudad.",
	["Further in."] = "Más adentro.",
	["Further in. Many groups skip him."] = "Más adentro. Muchos grupos se lo saltan.",
	["Further west, in a nook at the Magus Commerce Exchange."] = "Más al oeste, en un rincón del Magus Commerce Exchange.",
	["Gadgets, guns and bombs. Pairs with Mining."] = "Artilugios, armas de fuego y bombas. Combina con Minería.",
	["Game Menu > Edit Mode"] = "Menú de juego > Modo edición",
	["Game Menu, Edit Mode: move the bars, the minimap and chat"] = "Menú de juego, Modo edición: mueve las barras, el minimapa y el chat",
	["Game check"] = "Comprobación del juego",
	["Game check finished. Type /reload so the results are saved."] = "Comprobación terminada. Escribe /reload para que se guarden los resultados.",
	["Game options that make a first character easier to play, one click each."] = "Opciones del juego que facilitan jugar un primer personaje, con un clic cada una.",
	["Gameplay"] = "Experiencia de juego",
	["Gathering"] = "Recolección",
	["Gathers herbs. Pairs with Alchemy, or sell what you pick."] = "Recoge hierbas. Combina con Alquimia, o vende lo que recojas.",
	["Gathers ore and stone. Pairs with Blacksmithing or Engineering."] = "Extrae mineral y piedra. Combina con Herrería o Ingeniería.",
	["Gear"] = "Equipo",
	["Gear %d%%"] = "Equipo %d%%",
	["Gear nearly broken."] = "Equipo casi roto.",
	["General: talk to everyone in the area."] = "General: habla con todos en la zona.",
	["Ghost Wolf, your run-fast form, casts faster and works indoors."] = "Lobo fantasmal, tu forma para correr rápido, se lanza más rápido y funciona en interiores.",
	["Gives you a little protection against spells, and some mana back."] = "Te da un poco de protección contra hechizos, y algo de maná.",
	["Gives you more Armor, based on your Intellect."] = "Te da más Armadura, según tu Intelecto.",
	["Go back to the ramp and follow it up and around into a big cave with many crossing paths."] = "Vuelve a la rampa y síguela hacia arriba y alrededor hasta una gran cueva con muchos caminos cruzados.",
	["Go back to the split and take the left path with purple crystals."] = "Vuelve a la bifurcación y toma el camino de la izquierda con cristales morados.",
	["Go down the stairs heading east into the first area."] = "Baja las escaleras hacia el este hasta la primera zona.",
	["Go down to the Barov Family Vault with its six rooms."] = "Baja a la cripta de la familia Barov con sus seis salas.",
	["Go forward into the graveyard and on to a burned house with a fireplace."] = "Avanza hasta el cementerio y sigue hasta una casa quemada con chimenea.",
	["Go in and fight the first bug packs."] = "Entra y lucha contra los primeros grupos de insectos.",
	["Go in from the Blackrock Depths side and follow the lava tunnel to the first boss."] = "Entra por el lado de las Profundidades de Roca Negra y sigue el túnel de lava hasta el primer jefe.",
	["Go in through the cave and follow the winding path uphill between rough buildings."] = "Entra por la cueva y sigue el camino serpenteante cuesta arriba entre edificios toscos.",
	["Go in through the portal and enter the temple's first level."] = "Cruza el portal y entra en el primer nivel del templo.",
	["Go into Blackrock Mountain, climb down the big chain, go through Forgewright's Tomb and down another chain, then through the Grinding Quarry. Go left to the Masonry. The portal is in the far corner."] = "Entra en la Montaña Roca Negra, baja por la gran cadena, atraviesa la tumba de Forgewright y baja por otra cadena, y luego cruza la Grinding Quarry. Ve a la izquierda hasta la Masonry. El portal está en la esquina del fondo.",
	["Go on to the Dark Iron Highway. The gates need a Shadowforge Key or a rogue with lockpicking."] = "Sigue hasta la Dark Iron Highway. Las puertas necesitan una Llave Forjatiniebla o un pícaro que sepa forzar cerraduras.",
	["Go on to the Lost Dig Site where the orcs work. Do not pull too many at once."] = "Sigue hasta la Excavación Olvidada donde trabajan los orcos. No atraigas demasiados a la vez.",
	["Go straight ahead from the entrance. The jail is shaped like a T: you can clear the left and right wings in any order."] = "Sigue recto desde la entrada. La cárcel tiene forma de T: puedes limpiar las alas izquierda y derecha en cualquier orden.",
	["Go through Upper Blackrock Spire to the raid door. You need an attunement quest to enter."] = "Atraviesa la Cumbre de Roca Negra Superior hasta la puerta de la banda. Necesitas una misión de armonización para entrar.",
	["Go through the main gate into the living part. Fight across the market and the streets."] = "Cruza la puerta principal hacia la parte viva. Lucha a través del mercado y las calles.",
	["Go to the Cleft of Shadow, the cave in the middle of Orgrimmar, and follow the path down. The way in is at the bottom."] = "Ve a la Sima de las Sombras, la cueva en el centro de Orgrimmar, y sigue el camino hacia abajo. La entrada está al fondo.",
	["Go to the flight master in %s"] = "Ve al maestro de vuelo de %s",
	["Go up the stairs to the ring round the top. Six troll mini bosses stand on platforms around it. All six must die before the Prophet can be reached."] = "Sube las escaleras hasta el anillo que rodea la cima. Seis minijefes trols esperan en plataformas a su alrededor. Los seis deben morir antes de poder llegar al Profeta.",
	["Gold and more"] = "Oro y más",
	["Gold on all of them: %s"] = "Oro en todos ellos: %s",
	["Gold pays for new abilities, repairs, riding and gear. You earn it from quests, from selling things and from what enemies drop."] = "El oro paga nuevas facultades, reparaciones, equitación y equipo. Lo ganas con misiones, vendiendo cosas y con lo que sueltan los enemigos.",
	["Gold: much tougher, best with a group. Silver: rare, better loot."] = "Oro: mucho más duro, mejor en grupo. Plata: raro, mejor botín.",
	["Good at"] = "Bueno en",
	["Good places to start"] = "Buenos sitios para empezar",
	["Gourmand: food effects last longer"] = "Gastronomía: los efectos de la comida duran más",
	["Graveyard wing, levels 30 to 38. Its portal is the one on the far left as you walk in. No key needed."] = "Ala del Cementerio, niveles 30 a 38. Su portal es el de más a la izquierda según entras. No hace falta llave.",
	["Green or grey"] = "Verde o gris",
	["Grey !"] = "! gris",
	["Grey items are junk and safe to sell to any vendor. Bags fill up fast, so sell often."] = "Los objetos grises son chatarra y puedes venderlos sin problema a cualquier vendedor. Las bolsas se llenan rápido, así que vende a menudo.",
	["Grey items are junk. Selling them is safe."] = "Los objetos grises son chatarra. Venderlos es seguro.",
	["Grey items sell to any vendor. Keep what you can use."] = "Los objetos grises se venden a cualquier vendedor. Quédate lo que puedas usar.",
	["Grey quests"] = "Misiones grises",
	["Group"] = "Grupo",
	["Grouping"] = "Agruparse",
	["Groups"] = "Grupos",
	["Guide"] = "Guía",
	["Hammer of Justice stuns an enemy that is hitting your friend."] = "Martillo de justicia aturde a un enemigo que está golpeando a tu amigo.",
	["Hammer of Justice, a stun, is ready again sooner."] = "Martillo de justicia, un aturdimiento, vuelve a estar listo antes.",
	["Handle the skeletons he calls."] = "Encárgate de los esqueletos que invoca.",
	["Hands"] = "Manos",
	["Happiness"] = "Felicidad",
	["Happy: 125% damage. Content: 100%. Unhappy: 75%."] = "Feliz: 125 % de daño. Contenta: 100 %. Infeliz: 75 %.",
	["Hardcore"] = "Hardcore",
	["Hated"] = "Odiado",
	["He burns anyone close."] = "Quema a cualquiera que esté cerca.",
	["He calls a stone monster. Kill the seer helper first, and mark the targets."] = "Invoca un monstruo de piedra. Mata primero al ayudante vidente y marca los objetivos.",
	["He calls four wolves at 80% health. Be ready to pick them up, then kill them."] = "Invoca cuatro lobos al llegar al 80%. Prepárate para recogerlos y luego mátalos.",
	["He calls helpers, and again at half health. Focus him, not the helpers. He is the last boss."] = "Invoca ayudantes, y otra vez a media salud. Céntrate en él, no en los ayudantes. Es el último jefe.",
	["He can put people to sleep. Have someone ready to remove it, especially from the tank."] = "Puede dormir a la gente. Ten a alguien listo para quitarlo, sobre todo al tanque.",
	["He can take over a player's mind. Be ready to swap tank or healer."] = "Puede controlar la mente de un jugador. Prepárate para cambiar de tanque o sanador.",
	["He casts a big blast. Step away when he starts. A chest behind him holds the Scarlet Key."] = "Lanza una gran explosión. Apártate cuando empiece. Un cofre detrás de él tiene la Llave Escarlata.",
	["He casts fire. Kill him quickly. Rare bosses can also show up in this wing."] = "Lanza fuego. Mátalo rápido. En esta ala también pueden aparecer jefes raros.",
	["He drops a wand that casters like. Interrupt his cooking, which heals him."] = "Suelta una varita que gusta a los lanzadores. Interrumpe su cocina, que lo sana.",
	["He drops the Shaft of Tsol, needed for Ironaya."] = "Suelta el Shaft of Tsol, necesario para Hierraya.",
	["He gives the tank a heavy bleed. Cure it if you can."] = "Provoca al tanque un fuerte sangrado. Cúralo si puedes.",
	["He has no helpers, but he hits hard. Use defences and save mana."] = "No tiene ayudantes, pero pega fuerte. Usa defensas y ahorra maná.",
	["He has two helpers and a poison. Kill the helpers first and cure the poison. He is the last boss."] = "Tiene dos ayudantes y un veneno. Mata primero a los ayudantes y cura el veneno. Es el último jefe.",
	["He has two helpers. Kill them first, and fight in his room so other monsters stay away."] = "Tiene dos ayudantes. Mátalos primero, y lucha en su sala para que otros monstruos no se acerquen.",
	["He has two helpers. Kill them first, and interrupt his fire spell if you can."] = "Tiene dos ayudantes. Mátalos primero, e interrumpe su hechizo de fuego si puedes.",
	["He heals himself. Keep up the damage."] = "Se sana a sí mismo. Mantén el daño.",
	["He hits everyone close to him. Kill the guards with him first."] = "Golpea a todos los que tiene cerca. Mata primero a los guardias que lo acompañan.",
	["He is a caster. Pull him back from other monsters so the group is not hit from two sides."] = "Es un lanzador. Apártalo de otros monstruos para que al grupo no le golpeen por dos lados.",
	["He is strong. Stay near the tank."] = "Es fuerte. Quédate cerca del tanque.",
	["He is the first boss on the East list. Ask your group about the Crescent Key."] = "Es el primer jefe de la lista del Este. Pregunta a tu grupo por la Llave Creciente.",
	["He is the last boss of the dungeon."] = "Es el último jefe de la mazmorra.",
	["He jumps to random players. Cure his curse."] = "Salta a jugadores al azar. Cura su maldición.",
	["He keeps summoning spirit boars. Kill them as they come."] = "No para de invocar jabalíes espirituales. Mátalos según vengan.",
	["He may stand off the main road, with wolves."] = "Puede estar fuera del camino principal, con lobos.",
	["He rises from the water in the final room after the Disciple's ritual."] = "Sale del agua en la última sala tras el ritual del Discípulo.",
	["He sends people to side rooms. Kill the helpers and come back."] = "Envía a la gente a salas laterales. Mata a los ayudantes y vuelve.",
	["He splits into copies. Kill the real one."] = "Se divide en copias. Mata al verdadero.",
	["He summons helpers and tries to control players."] = "Invoca ayudantes e intenta controlar a los jugadores.",
	["He takes control of a player. Heal them and stop damage to them."] = "Toma el control de un jugador. Sánalo y no le hagas daño.",
	["He wakes stone helpers during the fight. They fall when he dies, so keep the damage on him."] = "Despierta ayudantes de piedra durante el combate. Caen cuando él muere, así que mantén el daño en él.",
	["He wanders the stream and is often skipped. A plain fight if you want him."] = "Recorre el arroyo y muchos se lo saltan. Un combate sencillo si lo quieres.",
	["Head"] = "Cabeza",
	["Head south along the left wall and turn right past the three ghost citizens."] = "Ve al sur por la pared izquierda y gira a la derecha pasados los tres ciudadanos fantasma.",
	["Heal and Greater Heal cast faster, so hurt allies get help sooner."] = "Curar y Curación superior se lanzan más rápido, así que los aliados heridos reciben ayuda antes.",
	["Heal the tank through the curse."] = "Sana al tanque durante la maldición.",
	["Heal your group with Holy Light and Flash of Light. You also wear heavy armor, so you can take a hit if an enemy gets to you."] = "Sana a tu grupo con Luz Sagrada y Destello de Luz. También llevas armadura pesada, así que aguantas un golpe si un enemigo llega hasta ti.",
	["Heal, Greater Heal and Prayer of Mending cost less mana."] = "Curar, Curación superior y Rezo de alivio cuestan menos maná.",
	["Healer"] = "Sanador",
	["Healers should watch for raptor bleeds."] = "Los sanadores deben vigilar los sangrados de los raptores.",
	["Healing Touch and Tranquility cost less Mana."] = "Toque curativo y Tranquilidad cuestan menos maná.",
	["Healing Touch casts faster, and it opens Nature's Swiftness."] = "Toque curativo se lanza más rápido, y abre Rapidez de la Naturaleza.",
	["Healing Wave casts faster, so you can heal yourself sooner."] = "Onda de curación se lanza más rápido, así que puedes sanarte antes.",
	["Healing Wave casts faster, so your big heal lands sooner."] = "Onda de curación se lanza más rápido, así que tu gran sanación llega antes.",
	["Healing Wave heals more."] = "Onda de curación sana más.",
	["Healing spells cost less mana and you miss less often."] = "Los hechizos de sanación cuestan menos maná y fallas menos.",
	["Healing spells cost less mana, so you can heal for longer."] = "Los hechizos de sanación cuestan menos maná, así que puedes sanar más tiempo.",
	["Heals the group, or casts shadow spells."] = "Sana al grupo, o lanza hechizos de sombras.",
	["Heals you a little after a heavy hit."] = "Te sana un poco tras un golpe fuerte.",
	["Heals your party from your Shadow damage, and it opens Shadowform."] = "Sana a tu grupo con tu daño de Sombras, y abre Forma de las Sombras.",
	["Heals your target and the party members near them over a short time."] = "Sana a tu objetivo y a los miembros del grupo cercanos durante poco tiempo.",
	["Health"] = "Salud",
	["Health low? Cast Holy Light between fights, or Flash of Light in a pinch."] = "¿Poca salud? Lanza Luz Sagrada entre combates, o Destello de Luz en un apuro.",
	["Health low? Step back and cast Healing Wave on yourself."] = "¿Poca salud? Retrocede y lánzate Onda de curación.",
	["Hearth"] = "Piedra",
	["Hearthstone"] = "Piedra de hogar",
	["Help and data"] = "Ayuda y datos",
	["Helps you start strong when you change into Bear Form or Cat Form."] = "Te ayuda a empezar fuerte cuando cambias a Forma de oso o Forma felina.",
	["Her bite is poison. Bring a cure if you can."] = "Su mordisco es venenoso. Lleva una cura si puedes.",
	["Her shield blocks spells. Use weapons or wait."] = "Su escudo bloquea los hechizos. Usa armas o espera.",
	["Herbalism"] = "Botánica",
	["Here"] = "Aquí",
	["Heroic Strike costs less Rage."] = "Golpe heroico cuesta menos Ira.",
	["Hide behind an ice block when he casts."] = "Escóndete tras un bloque de hielo cuando lance.",
	["Hide in combat"] = "Ocultar en combate",
	["High"] = "Alto",
	["High Alert: notice hidden enemies sooner"] = "Alerta máxima: detectas antes a los enemigos ocultos",
	["His curse slows the tank. Remove it if you can."] = "Su maldición ralentiza al tanque. Quítala si puedes.",
	["His fire spell makes fire hit harder. Remove it if you can."] = "Su hechizo de fuego hace que el fuego pegue más. Quítalo si puedes.",
	["His shield bash often stuns. Strong Defias guards nearby may join in."] = "Su golpe de escudo suele aturdir. Fuertes guardias Defias cercanos pueden unirse.",
	["His shout can pull people out of healing range. Stay close to the healer."] = "Su grito puede sacar a la gente del alcance de sanación. Quédate cerca del sanador.",
	["His uppercut throws you back. Do not stand near the lava edge. Patrols can join in."] = "Su gancho te lanza hacia atrás. No te quedes cerca del borde de lava. Las patrullas pueden unirse.",
	["His vines root everyone near him. Stand well back, and keep the tank healed."] = "Sus enredaderas inmovilizan a todos los que están cerca. Mantente bien atrás y mantén sanado al tanque.",
	["Hits from a distance and fights beside a pet."] = "Ataca a distancia y lucha junto a una mascota.",
	["Hitting an enemy that has your Rend on it can make Overpower usable."] = "Golpear a un enemigo que tiene tu Desgarrar puede hacer usable Abrumar.",
	["Hold Mind Flay between Mind Blasts. It also slows the enemy so it reaches you later."] = "Mantén Despelleje mental entre Explosiones mentales. También ralentiza al enemigo para que tarde más en llegar a ti.",
	["Hold the enemies' attention in a dungeon with a shield and Righteous Fury, and take hits while your group does the damage."] = "Retén la atención de los enemigos en una mazmorra con escudo y Furia justa, y aguanta los golpes mientras tu grupo hace el daño.",
	["Hold the enemies' attention in a dungeon with a shield, and take the hits while your group does the damage."] = "Retén la atención de los enemigos en una mazmorra con escudo, y aguanta los golpes mientras tu grupo hace el daño.",
	["Holds one Humanoid enemy still until you hit it, and it opens Unsealed Wrath."] = "Inmoviliza a un enemigo humanoide hasta que lo golpeas, y abre Cólera desellada.",
	["Holy Light and Flash of Light heal for more, so you can heal yourself."] = "Luz Sagrada y Destello de Luz sanan más, así que puedes sanarte.",
	["Holy Light and Flash of Light heal you for more."] = "Luz Sagrada y Destello de Luz te sanan más.",
	["Holy Light, Flash of Light and Holy Shock heal for more."] = "Luz Sagrada, Destello de Luz y Choque Sagrado sanan más.",
	["Holy Shield makes you block much more for a while. Use it before a hard hit."] = "Escudo Sagrado te hace bloquear mucho más durante un rato. Úsalo antes de un golpe fuerte.",
	["Holy Shock gets more critical heals on friends who do not have your Oath."] = "Choque Sagrado consigue más sanaciones críticas en amigos que no tienen tu Juramento.",
	["Holy Shock heals a friend, or hurts an enemy. Use it whenever it is ready."] = "Choque Sagrado sana a un amigo o daña a un enemigo. Úsalo siempre que esté listo.",
	["Holy Strike hits harder and keeps your Judgements on the enemy fresh."] = "Golpe Sagrado pega más fuerte y mantiene frescas tus Sentencias sobre el enemigo.",
	["Holy Strike is ready sooner, and works with your Holy Shield."] = "Golpe Sagrado está listo antes, y funciona con tu Escudo Sagrado.",
	["Holy Strike keeps more enemy attention on you, and with Righteous Fury it cuts damage you take."] = "Golpe Sagrado mantiene más atención enemiga sobre ti, y con Furia justa reduce el daño que recibes.",
	["Home"] = "Inicio",
	["Home: %s"] = "Hogar: %s",
	["Home: %s. %s"] = "Hogar: %s. %s",
	["Home: not set"] = "Hogar: sin fijar",
	["Honored"] = "Honrado",
	["Horde players can enter too, but its quests are for the Alliance."] = "Los jugadores de la Horda también pueden entrar, pero sus misiones son para la Alianza.",
	["Hostile"] = "Hostil",
	["How to get there"] = "Cómo llegar",
	["Hunters keep their spare pets here."] = "Los cazadores guardan aquí sus mascotas de reserva.",
	["Hurt after a fight? Rest and let your health and mana fill up before the next one."] = "¿Herido tras un combate? Descansa y deja que se llenen tu salud y tu maná antes del siguiente.",
	["Hurt badly? Swiftmend heals you at once if you have Rejuvenation or Regrowth on you."] = "¿Muy herido? Arreglo rápido te sana al instante si tienes Rejuvenecimiento o Recrecimiento.",
	["Hurts an enemy or heals a friend."] = "Daña a un enemigo o sana a un amigo.",
	["Hyjal Summit"] = "Cima Hyjal",
	["Ice Lance hits much harder on a frozen enemy. Cast it right after Frost Nova."] = "Lanza de hielo pega mucho más fuerte a un enemigo congelado. Lánzala justo después de Nova de Escarcha.",
	["If a fight goes badly, run toward a town or a guard. Your ruleset decides who can attack you: PvE only when you choose, PvP almost always."] = "Si un combate va mal, corre hacia un pueblo o un guardia. Tu tipo de reino decide quién puede atacarte: en JcE solo cuando tú eliges, en JcJ casi siempre.",
	["If he is not there, just walk on."] = "Si no está, sigue adelante.",
	["If it dies"] = "Si muere",
	["If the flight master does not list it, you have not found it yet. Fly as close as you can."] = "Si el maestro de vuelo no lo muestra, aún no lo has descubierto. Vuela lo más cerca que puedas.",
	["If you die you can still heal for a short time, and it opens Prayer of Mending."] = "Si mueres aún puedes sanar durante un momento, y abre Rezo de alivio.",
	["If you die: release, run back to your body, and come back to life in a safe spot. Use the Spirit Healer only when you cannot reach your body."] = "Si mueres: libera tu espíritu, corre hasta tu cuerpo y vuelve a la vida en un lugar seguro. Usa el ángel de la Resurrección solo si no puedes llegar a tu cuerpo.",
	["In %s"] = "En %s",
	["In Bear Form use Lacerate again and again so the bleed grows."] = "En Forma de oso usa Lacerar una y otra vez para que el sangrado crezca.",
	["In Feralas, in the ruins. The East door needs no key. West and North need the Crescent Key, which comes from the East part."] = "En Feralas, en las ruinas. La puerta Este no necesita llave. Oeste y Norte necesitan la Llave Creciente, que se consigue en la parte Este.",
	["In Ironforge, go to the king's hall and turn left to a web-covered passage. Follow it down. Do not fall off the edge."] = "En Forjaz, ve a la sala del rey y gira a la izquierda hacia un pasaje cubierto de telarañas. Síguelo hacia abajo. No te caigas por el borde.",
	["In Silverpine Forest, in the mountains just north of Pyrewood Village, walk up to the big keep gate."] = "En el Bosque de Argénteos, en las montañas justo al norte de Aldea Piroleña, sube hasta la gran puerta del castillo.",
	["In Stalker's Thicket, with two helper hunters. Some raptors are hidden."] = "En la Fronda del Acechador, con dos cazadores ayudantes. Algunos raptores están ocultos.",
	["In Stormwind City, go to the canals near the Mage Quarter. The gate to the Stockade is on the water's edge."] = "En Ciudad de Ventormenta, ve a los canales cerca del Barrio de los Magos. La puerta de Las Mazmorras está a la orilla del agua.",
	["In Tirisfal Glades, at the Undercity gate. Reports say the stairs are on the left before the keep."] = "En los Claros de Tirisfal, en la puerta de Entrañas. Dicen que las escaleras están a la izquierda antes del torreón.",
	["In Westfall, in the town of Moonbrook, go into the big Defias Hideout building in the south-west corner. Follow the cave maze down to the bottom."] = "En los Páramos de Poniente, en el pueblo de Arroyo de la Luna, entra en el gran edificio escondite de los Defias en la esquina suroeste. Sigue el laberinto de cuevas hasta el fondo.",
	["In a cave in the hills of Dustwallow Marsh. You need an attunement quest to enter."] = "En una cueva de las colinas del Marjal Revolcafango. Necesitas una misión de armonización para entrar.",
	["In a fight"] = "En combate",
	["In a frozen lair at the back of the fortress."] = "En una guarida helada al fondo de la fortaleza.",
	["In a party of %d"] = "En un grupo de %d",
	["In a raid of %d"] = "En una banda de %d",
	["In a room of the keep that is packed with monsters."] = "En una sala del torreón repleta de monstruos.",
	["In a room of the main keep, full of guards."] = "En una sala del torreón principal, llena de guardias.",
	["In a room past Theka. He looks friendly until you step in."] = "En una sala pasado Theka. Parece amistoso hasta que entras.",
	["In a side hall."] = "En un pasillo lateral.",
	["In a small room at the end of the right-hand side path, soon after the first ramp."] = "En una sala pequeña al final del camino lateral derecho, poco después de la primera rampa.",
	["In an emergency, Nature's Swiftness makes your next heal instant."] = "En una emergencia, Rapidez de la Naturaleza hace instantánea tu siguiente sanación.",
	["In an inn or a city: your rest is building up"] = "En una posada o ciudad: tu descanso se va acumulando",
	["In hand"] = "En mano",
	["In hand, low"] = "En mano, baja",
	["In his arena to the west, past the ghost citizens."] = "En su arena al oeste, pasados los ciudadanos fantasma.",
	["In his own room. Guides call him the last boss."] = "En su propia sala. Las guías lo llaman el último jefe.",
	["In his tent, the last stop in the dungeon."] = "En su tienda, la última parada de la mazmorra.",
	["In his workshop, inside a big machine called the Shredder."] = "En su taller, dentro de una gran máquina llamada la Trituradora.",
	["In one of the two cell wings."] = "En una de las dos alas de celdas.",
	["In real danger, use Lay on Hands, a big heal you can only use now and then."] = "En peligro real, usa Imposición de manos, una gran sanación que solo puedes usar de vez en cuando.",
	["In the Alchemy Lab."] = "En el laboratorio de alquimia.",
	["In the Barov Family Vault, once the six rooms are cleared."] = "En la cripta de la familia Barov, cuando las seis salas estén limpias.",
	["In the Black Vault, with his hound."] = "En la Black Vault, con su perro.",
	["In the Black Vault. Opening all twelve relic coffer doors brings out this fight."] = "En la Black Vault. Abrir las doce puertas de los cofres de reliquias provoca este combate.",
	["In the Capital Gardens, a walking tree."] = "En los Capital Gardens, un árbol que camina.",
	["In the Cathedral wing, in the first part."] = "En el ala de la Catedral, en la primera parte.",
	["In the Chamber of Enchantment."] = "En la Chamber of Enchantment.",
	["In the Construct Wing."] = "En el ala de los Ensamblajes.",
	["In the Crimson buildings of the Living part."] = "En los edificios carmesí de la parte Viva.",
	["In the East part."] = "En la parte Este.",
	["In the Graveyard wing, near the start."] = "En el ala del Cementerio, cerca del principio.",
	["In the Grim Guzzler, the dwarf bar. He fights if you threaten him in talk."] = "En el Grim Guzzler, el bar de los enanos. Lucha si le amenazas en la conversación.",
	["In the Imperial Seat, with the Emperor."] = "En el Imperial Seat, con el Emperador.",
	["In the Lair of the Chosen, after the six troll mini bosses are dead. Ogom the Wretched stands with him."] = "En la Lair of the Chosen, cuando los seis minijefes trols estén muertos. Ogom el Miserable está con él.",
	["In the Library wing, with his dogs."] = "En el ala de la Biblioteca, con sus perros.",
	["In the Living part. Mostly wanted for a smithing quest."] = "En la parte Viva. Sobre todo se le busca por una misión de herrería.",
	["In the Lushwater Oasis, in the middle of The Barrens, find the cave called the Cavern of Mists. Follow the winding tunnel down to a big pool."] = "En el Oasis Aguaverde, en el centro de Los Baldíos, busca la cueva llamada Cavern of Mists. Sigue el túnel serpenteante hasta un gran estanque.",
	["In the Manufactory, the machine hall."] = "En la Manufactory, la sala de las máquinas.",
	["In the Military Wing."] = "En el ala Militar.",
	["In the North part, a drunk ogre at a table."] = "En la parte Norte, un ogro borracho en una mesa.",
	["In the North part, by the throne room."] = "En la parte Norte, junto a la sala del trono.",
	["In the North part, near the throne room."] = "En la parte Norte, cerca de la sala del trono.",
	["In the North part."] = "En la parte Norte.",
	["In the Pit of Refuse, to the right of the portal. Click the six shrines in the right order to wake him."] = "En el Pit of Refuse, a la derecha del portal. Haz clic en los seis santuarios en el orden correcto para despertarlo.",
	["In the Plague Wing."] = "En el ala de la Peste.",
	["In the Reliquary of Kings, the room across the north bridge."] = "En el Reliquary of Kings, la sala al otro lado del puente norte.",
	["In the Riverglades, a cave to the west of the big fortress gates, near a meeting stone."] = "En Clarofluvial, una cueva al oeste de las grandes puertas de la fortaleza, cerca de una piedra de encuentro.",
	["In the Slaughterhouse at the end of the living part."] = "En el matadero al final de la parte viva.",
	["In the Spider Wing."] = "En el ala Arácnida.",
	["In the Summoners' Tomb: seven dwarf spirits, one after another."] = "En la Summoners' Tomb: siete espíritus enanos, uno tras otro.",
	["In the Undead part."] = "En la parte No-muerta.",
	["In the Viewing Room. A party member needs a related quest to start him."] = "En la Viewing Room. Un miembro del grupo necesita una misión relacionada para iniciarlo.",
	["In the Violet Chamber. Talk to Archmage Modera on the Violet Citadel steps to go in."] = "En la Violet Chamber. Habla con la archimaga Modera en las escaleras de la Ciudadela Violeta para entrar.",
	["In the Violet Hold, to the left in the streets."] = "En el Bastión Violeta, a la izquierda en las calles.",
	["In the West Garrison."] = "En la West Garrison.",
	["In the West part."] = "En la parte Oeste.",
	["In the Wetlands, take the winding path left of Thelgen Rock. The entrance is a cave at the end."] = "En Los Humedales, toma el camino serpenteante a la izquierda de Roca Thelgen. La entrada es una cueva al final.",
	["In the air phase, spread out and do not stand together."] = "En la fase aérea, separaos y no os quedéis juntos.",
	["In the area of the dragon bosses."] = "En la zona de los jefes dragón.",
	["In the basement of the Great Ossuary."] = "En el sótano del Great Ossuary.",
	["In the big round hall with columns, the last room."] = "En la gran sala redonda con columnas, la última sala.",
	["In the big tomb room at the end of the west corridor. He patrols the tomb."] = "En la gran sala de la tumba al final del pasillo oeste. Patrulla la tumba.",
	["In the biggest cave at the end."] = "En la cueva más grande del final.",
	["In the cabin at the very top of the ship, past Captain Greenskin."] = "En el camarote de lo más alto del barco, pasado el Capitán Verdetez.",
	["In the captain's area at the back of the ship."] = "En la zona del capitán al fondo del barco.",
	["In the cell block, with two guards."] = "En el bloque de celdas, con dos guardias.",
	["In the cell block."] = "En el bloque de celdas.",
	["In the central Runeweaver Square. Speak to Magus Fansy Goodbringer to drop the barrier."] = "En la plaza central Runeweaver Square. Habla con el magus Fansy Goodbringer para quitar la barrera.",
	["In the central cave, on a high ledge. She stands at one of several circles."] = "En la cueva central, en una cornisa alta. Está en uno de varios círculos.",
	["In the ceremonial chamber just before the last room."] = "En la cámara ceremonial justo antes de la última sala.",
	["In the courtyard with the pool and the gong, tucked round a corner."] = "En el patio con el estanque y el gong, escondido tras una esquina.",
	["In the courtyard. Touch the statue with glowing eyes to start waves."] = "En el patio. Toca la estatua de ojos brillantes para empezar las oleadas.",
	["In the engineering labs."] = "En los laboratorios de ingeniería.",
	["In the far south of Silithus, at the big gate to the Ahn'Qiraj temple. Ask the raid leader if the door is open."] = "En el extremo sur de Silithus, en la gran puerta del templo de Ahn'Qiraj. Pregunta al líder de banda si la puerta está abierta.",
	["In the far south of Silithus, outside the big gate to the Ahn'Qiraj temple. Ask the raid leader if the door is open."] = "En el extremo sur de Silithus, fuera de la gran puerta del templo de Ahn'Qiraj. Pregunta al líder de banda si la puerta está abierta.",
	["In the far south-west of The Barrens, push through the maze of thorns and quilboar to the portal at its end."] = "En el extremo suroeste de Los Baldíos, abríos paso por el laberinto de espinas y jabaespines hasta el portal del final.",
	["In the first big room, where a gong stands."] = "En la primera sala grande, donde hay un gong.",
	["In the flooded tomb under the pool, reached by swimming."] = "En la tumba inundada bajo el estanque, a la que se llega nadando.",
	["In the garden next to the pylon."] = "En el jardín junto al pilón.",
	["In the goblin foundry room further along."] = "En la sala de la fundición goblin, más adelante.",
	["In the keep, with a swarm of bats."] = "En el torreón, con un enjambre de murciélagos.",
	["In the last cave. A huge sea creature."] = "En la última cueva. Una enorme criatura marina.",
	["In the last room at the top of the keep, with three worgen."] = "En la última sala en lo alto del castillo, con tres huargen.",
	["In the last room of the Cathedral wing, with Scarlet Commander Mograine."] = "En la última sala del ala de la Catedral, con el comandante Escarlata Mograine.",
	["In the last room."] = "En la última sala.",
	["In the left-hand wing: climb the winding path up to the Pit of Fangs."] = "En el ala izquierda: sube el camino serpenteante hasta el Pit of Fangs.",
	["In the lower rooms of the first part."] = "En las salas inferiores de la primera parte.",
	["In the main keep, with helpers around him."] = "En el torreón principal, con ayudantes a su alrededor.",
	["In the natural cave beyond the tombs, with Dark Iron dwarves around."] = "En la cueva natural pasadas las tumbas, rodeado de enanos Hierro Negro.",
	["In the north of Stranglethorn Vale. Walk up the path from the village into the stone gate."] = "En el norte de la Vega de Tuercespina. Sube por el camino desde el poblado hasta la puerta de piedra.",
	["In the north of the Badlands, near Loch Modan, find the excavation tunnels and go in. Strong monsters wait in the tunnels."] = "En el norte de las Tierras Inhóspitas, cerca de Loch Modan, busca los túneles de excavación y entra. En los túneles esperan monstruos fuertes.",
	["In the north-east corner of Tirisfal Glades. The four wing portals sit in the main building. The Scarlet Key opens the locked doors; the Graveyard needs none."] = "En la esquina noreste de los Claros de Tirisfal. Los cuatro portales de las alas están en el edificio principal. La Llave Escarlata abre las puertas cerradas; el Cementerio no la necesita.",
	["In the north-west corner of Ashenvale, at the Zoram Strand, find the sunken ruins. Swim down into the pool at the bottom, then follow the narrow cave."] = "En la esquina noroeste de Vallefresno, en La Ensenada de Zoram, busca las ruinas hundidas. Bucea hasta el fondo del estanque y sigue la estrecha cueva.",
	["In the north-west corner of Tanaris. Walk in through the big gate of the troll city."] = "En la esquina noroeste de Tanaris. Entra por la gran puerta de la ciudad trol.",
	["In the north-west of Dun Morogh, take the lift down to the outer tunnels, then walk to the dungeon portal."] = "En el noroeste de Dun Morogh, baja en el ascensor a los túneles exteriores y camina hasta el portal de la mazmorra.",
	["In the panther temple."] = "En el templo de la pantera.",
	["In the pool, called out with fishing bait."] = "En el estanque, se le atrae con cebo de pesca.",
	["In the sewer's Underbelly, past three big pipes, in a summoning circle."] = "En los bajos fondos de la cloaca, pasadas tres grandes tuberías, en un círculo de invocación.",
	["In the snake temple."] = "En el templo de la serpiente.",
	["In the south-east of The Barrens, cross the maze of thorns and quilboar to the portal at its end."] = "En el sureste de Los Baldíos, cruza el laberinto de espinas y jabaespines hasta el portal del final.",
	["In the southernmost room of the Detention Block. She drops the Prison Cell Key."] = "En la sala más al sur del bloque de detención. Suelta la llave de la celda.",
	["In the spider temple."] = "En el templo de la araña.",
	["In the streets of the Living part."] = "En las calles de la parte Viva.",
	["In the tiger temple."] = "En el templo del tigre.",
	["In the water under the last boss's platform."] = "En el agua bajo la plataforma del último jefe.",
	["In this zone"] = "En esta zona",
	["Incense Candle"] = "Vela de incienso",
	["Inn"] = "Posada",
	["Inns and rest"] = "Posadas y descanso",
	["Inside Blackrock Mountain, on its east side. Take the door by the meeting stone and climb the path, or jump down from the balcony where the gnome Bodley stands, which skips the monsters."] = "Dentro de la Montaña Roca Negra, en su lado este. Toma la puerta junto a la piedra de encuentro y sube el camino, o salta desde el balcón donde está el gnomo Bodley, lo que evita a los monstruos.",
	["Inside the dungeon, this page ticks off each boss as it falls."] = "Dentro de la mazmorra, esta página marca cada jefe según cae.",
	["Intellect"] = "Intelecto",
	["Intellect first, as it adds attack power and Mana. Then Stamina. A slow two-handed weapon, or a one-hander and shield, works well."] = "Primero Intelecto, porque añade poder de ataque y maná. Luego Aguante. Un arma de dos manos lenta, o una de una mano y escudo, funciona bien.",
	["Intellect first, then Spirit and Stamina. Look for gear that adds healing, in cloth or leather, and a staff or a held item."] = "Primero Intelecto, luego Espíritu y Aguante. Busca equipo que añada sanación, de tela o cuero, y un bastón o un objeto de mano.",
	["Intellect first, then Spirit and Stamina. Use a staff or a wand, and gear that adds Spell Damage."] = "Primero Intelecto, luego Espíritu y Aguante. Usa un bastón o una varita, y equipo que añada daño con hechizos.",
	["Intellect first, then Spirit and Stamina. Use a staff, a wand, or a held item that adds healing."] = "Primero Intelecto, luego Espíritu y Aguante. Usa un bastón, una varita o un objeto de mano que añada sanación.",
	["Intellect first, then Stamina and Spirit. Look for gear that adds healing, and a shield or a held item."] = "Primero Intelecto, luego Aguante y Espíritu. Busca equipo que añada sanación, y un escudo o un objeto de mano.",
	["Intellect first, then Stamina and Spirit. Look for items that add healing."] = "Primero Intelecto, luego Aguante y Espíritu. Busca objetos que añadan sanación.",
	["Intellect first, then Stamina and Spirit. Use a staff or a wand, and cloth armor."] = "Primero Intelecto, luego Aguante y Espíritu. Usa un bastón o una varita, y armadura de tela.",
	["Interrupt her hex."] = "Interrumpe su maleficio.",
	["Interrupt her mana burn."] = "Interrumpe su quemadura de maná.",
	["Interrupt her spells."] = "Interrumpe sus hechizos.",
	["Interrupt his big spells."] = "Interrumpe sus grandes hechizos.",
	["Interrupt his enrage if you can."] = "Interrumpe su enfurecimiento si puedes.",
	["Interrupt his healing spell."] = "Interrumpe su hechizo de sanación.",
	["Interrupt his life drain. Three waves come from both sides."] = "Interrumpe su drenaje de vida. Llegan tres oleadas por ambos lados.",
	["Interrupt his shooting."] = "Interrumpe sus disparos.",
	["Interrupt his spells."] = "Interrumpe sus hechizos.",
	["Ironaya wakes only when someone uses two special items. Ask your group."] = "Hierraya solo despierta cuando alguien usa dos objetos especiales. Pregunta a tu grupo.",
	["Ironforge"] = "Forjaz",
	["It counts when the raid is done."] = "Cuenta cuando se completa la banda.",
	["It is meant for levels %d to %d and gives little experience now."] = "Está pensada para niveles %d a %d y ahora da poca experiencia.",
	["It is meant for levels %d to %d. Monsters here are much stronger than you."] = "Está pensada para niveles %d a %d. Aquí los monstruos son mucho más fuertes que tú.",
	["It learns an entrance the first time one of your characters walks in, and keeps it for all of them. Until then, ask your group to lead the way."] = "Aprende una entrada la primera vez que uno de tus personajes entra, y la guarda para todos. Hasta entonces, pide a tu grupo que te guíe.",
	["It learns from your kills and stops at your own level."] = "Aprende de tus muertes y se detiene en tu nivel.",
	["It rises as you fight with that kind of weapon."] = "Sube al luchar con ese tipo de arma.",
	["Items"] = "Objetos",
	["Items and enemies"] = "Objetos y enemigos",
	["Its level"] = "Su nivel",
	["Its sand storm slows and silences. Ranged fighters and healers should stay far away."] = "Su tormenta de arena ralentiza y silencia. Los luchadores a distancia y los sanadores deben quedarse lejos.",
	["Jobs and finding a group"] = "Profesiones y buscar grupo",
	["Join a party with other players"] = "Únete a un grupo con otros jugadores",
	["Journal"] = "Diario",
	["Judgement gives back Mana from your Seal, so fights cost you less."] = "Sentencia devuelve maná de tu Sello, así que los combates te cuestan menos.",
	["Judgement is ready again sooner, so you use it more often."] = "Sentencia vuelve a estar lista antes, así que la usas más a menudo.",
	["Judgement while Seal of Fury is on makes an enemy attack you. Use it on one hitting a friend."] = "Sentencia con Sello de furia activo hace que un enemigo te ataque. Úsala en uno que golpee a un amigo.",
	["Jump down to the cave floor, walk back to the central cave and take the much bigger side on the other hand."] = "Salta al suelo de la cueva, vuelve a la cueva central y toma el lado mucho más grande, al otro lado.",
	["Jump into the pool behind Verdan to drop back to the start area."] = "Salta al estanque detrás de Verdan para volver a la zona de inicio.",
	["Keep"] = "Guardar",
	["Keep Water Shield on between fights to win mana back."] = "Mantén Escudo de agua entre combates para recuperar maná.",
	["Keep Water Shield on you. It gives mana back as you are hit."] = "Mantén Escudo de agua puesto. Te devuelve maná cuando te golpean.",
	["Keep an eye on your Health. Rejuvenation on yourself between fights saves your healer."] = "Vigila tu Salud. Rejuvenecimiento sobre ti entre combates ayuda a tu sanador.",
	["Keep healing even after the poison hits."] = "Sigue sanando incluso después de que llegue el veneno.",
	["Keep monsters off the escort. Only start it if you have the quest."] = "Mantén a los monstruos lejos de la escolta. Empiézala solo si tienes la misión.",
	["Keep moving away from an enemy while you hit it."] = "Sigue alejándote de un enemigo mientras lo golpeas.",
	["Keep ranged players and healers out of his dust cloud."] = "Mantén a los jugadores a distancia y a los sanadores fuera de su nube de polvo.",
	["Keep ranged players away."] = "Mantén lejos a los jugadores a distancia.",
	["Keep ranged players out of his aura."] = "Mantén a los jugadores a distancia fuera de su aura.",
	["Keep the tank at full health."] = "Mantén al tanque con la salud llena.",
	["Keep the tank facing him, and everyone else away from the front."] = "Que el tanque lo mantenga encarado, y todos los demás lejos de su frente.",
	["Keeps a group of five alive with Healing Wave and, later, Chain Heal and Riptide. Stay back, watch health bars and spend mana wisely."] = "Mantiene con vida a un grupo de cinco con Onda de curación y, más tarde, Curación en cadena y Mareas vivas. Quédate atrás, vigila las barras de salud y gasta el maná con cabeza.",
	["Keeps everyone alive."] = "Mantiene a todos con vida.",
	["Keeps your group alive with healing spells that work over time. Wild Growth, late in the build, heals a whole party."] = "Mantiene con vida a tu grupo con hechizos de sanación con el tiempo. Crecimiento salvaje, al final de la build, sana a todo el grupo.",
	["Key Bindings"] = "Configurar teclado",
	["Kill all but one or two so the last boss does not spawn early."] = "Mata a todos menos uno o dos para que el último jefe no aparezca antes de tiempo.",
	["Kill all his friends within a few seconds of each other."] = "Mata a todos sus amigos con pocos segundos de diferencia.",
	["Kill all three bugs together."] = "Mata a los tres insectos a la vez.",
	["Kill both of his healers before him."] = "Mata a sus dos sanadores antes que a él.",
	["Kill four Bloodkeepers and use their blood on four braziers to bring him out."] = "Mata a cuatro Bloodkeepers y usa su sangre en cuatro braseros para hacerlo salir.",
	["Kill her bats and avoid the fire."] = "Mata a sus murciélagos y evita el fuego.",
	["Kill her first. Her bird helper comes with her."] = "Mátala primero. Su ayudante pájaro viene con ella.",
	["Kill her followers first."] = "Mata primero a sus seguidores.",
	["Kill her helpers on the ground."] = "Mata a sus ayudantes en el suelo.",
	["Kill him before his helpers."] = "Mátalo antes que a sus ayudantes.",
	["Kill him before more monsters join."] = "Mátalo antes de que se unan más monstruos.",
	["Kill him fast before he enrages."] = "Mátalo rápido antes de que se enfurezca.",
	["Kill him fast."] = "Mátalo rápido.",
	["Kill him first, then the priest. Healers stay far back."] = "Mátalo primero a él, luego al sacerdote. Los sanadores, bien atrás.",
	["Kill him first. His helpers disappear when he dies."] = "Mátalo primero. Sus ayudantes desaparecen cuando muere.",
	["Kill him, not the spirits around him. Killing one makes him call another."] = "Mátalo a él, no a los espíritus que lo rodean. Matar uno le hace invocar otro.",
	["Kill his fire spirits before they reach him."] = "Mata a sus espíritus de fuego antes de que lleguen a él.",
	["Kill his fire totem when it appears."] = "Mata su tótem de fuego cuando aparezca.",
	["Kill his healers first."] = "Mata primero a sus sanadores.",
	["Kill his helpers first and spread out."] = "Mata primero a sus ayudantes y separaos.",
	["Kill his helpers first: the acolyte, then the big one. Interrupt the acolyte's mana burn."] = "Mata primero a sus ayudantes: el acólito y luego el grande. Interrumpe la quemadura de maná del acólito.",
	["Kill his helpers when they rise."] = "Mata a sus ayudantes cuando se levanten.",
	["Kill his helpers with area damage."] = "Mata a sus ayudantes con daño de área.",
	["Kill his hound first and use no frost damage on him."] = "Mata primero a su perro y no uses daño de Escarcha contra él.",
