	["Neutral"] = "Neutral",
	["New player companion"] = "Compañero para jugadores nuevos",
	["New spells and new ranks are bought from your class trainer."] = "Los hechizos nuevos y los nuevos rangos se compran a tu instructor de clase.",
	["Next"] = "Próximo",
	["Next boss: %s  (%d of %d down)"] = "Próximo jefe: %s  (%d de %d caídos)",
	["Next boss: %s. Open the route to see the way and where each boss stands."] = "Próximo jefe: %s. Abre la ruta para ver el camino y dónde está cada jefe.",
	["Next in your build: %s (%d of %d)."] = "Siguiente en tu build: %s (%d de %d).",
	["Next is the Plague Wing."] = "Lo siguiente es el ala de la Peste.",
	["Next milestone"] = "Próximo hito",
