	["Next talent point"] = "Próximo punto de talento",
	["Next tip"] = "Siguiente consejo",
	["Next: %s"] = "Siguiente: %s",
	["Next: %s."] = "Siguiente: %s.",
	["Night"] = "Noche",
	["No Legacy Points yet"] = "Aún no hay puntos de legado",
	["No automatic queue. Ask in chat or use Looking For Group."] = "No hay cola automática. Pregunta en el chat o usa Buscar grupo.",
	["No build for your class yet"] = "Aún no hay build para tu clase",
	["No dungeon yet: the first opens at level %d"] = "Aún no hay mazmorra: la primera se abre a nivel %d",
	["No flight point for your side"] = "No hay punto de vuelo para tu bando",
	["No flight points listed"] = "No hay puntos de vuelo en la lista",
	["No home yet. Ask an innkeeper to set one."] = "Aún no tienes hogar. Pide a un tabernero que te fije uno.",
	["No professions"] = "Sin profesiones",
	["No quest hub listed for your side"] = "No hay centro de misiones para tu bando",
	["No zone is listed for your level. Look at All zones."] = "No hay ninguna zona para tu nivel. Mira Todas las zonas.",
	["None"] = "Ninguno",
	["None found yet"] = "Aún no se ha encontrado ninguno",
	["None of your flight points gets you closer. Every flight master you talk to on the way makes later trips quicker."] = "Ninguno de tus puntos de vuelo te acerca. Cada maestro de vuelo con el que hables por el camino hace más rápidos los viajes futuros.",
	["None yet"] = "Aún ninguno",
	["North of the Lost Dig Site, ringed by oil slimes."] = "Al norte de la Excavación Olvidada, rodeado de babosas de petróleo.",
	["North part, the ogre keep (Gordok Commons). The Crescent Key opens its door."] = "Parte Norte, el torreón ogro (Gordok Commons). La Llave Creciente abre su puerta.",
	["North-west corner of the Eastern Plaguelands, across the long stone bridge, into the Living part. The Eastwall Gate, a cave a little east, leads to the Undead part and needs a key."] = "Esquina noroeste de las Tierras de la Peste del Este, cruzando el largo puente de piedra, hacia la parte Viva. La Puerta de la Muralla del Este, una cueva un poco al este, lleva a la parte No-muerta y necesita una llave.",
	["North-west section. From the courtyard, go through the narrow stairs, turn right, then jump through the big window."] = "Sección noroeste. Desde el patio, sube por las escaleras estrechas, gira a la derecha y salta por el gran ventanal.",
	["Not a boss you walk to. It is the progress for the whole raid."] = "No es un jefe al que vayas. Es el progreso de toda la banda.",
	["Not better than what you wear: %s"] = "No es mejor que lo que llevas: %s",
	["Not during a fight. Try again when it is over."] = "No durante un combate. Inténtalo de nuevo cuando termine.",
	["Not in your bags"] = "No está en tus bolsas",
	["Not known here"] = "No se conoce aquí",
	["Not listed"] = "Sin datos",
	["Not on your action bars"] = "No está en tus barras de acción",
	["Not open yet: it needs more points in its tree first."] = "Aún no está abierto: primero necesita más puntos en su árbol.",
	["Not sure where talent points go?"] = "¿No sabes dónde van los puntos de talento?",
	["Nothing else joins him, so put everything on him."] = "Nadie más se une a él, así que vuelca todo sobre él.",
	["Nothing found"] = "No se ha encontrado nada",
	["Nothing known yet."] = "Aún no se sabe nada.",
	["Nothing needs doing. Your skills rise as you gather and make things."] = "No hay nada que hacer. Tus habilidades suben al recolectar y fabricar cosas.",
	["Nothing needs repair yet. %s is the most worn, at %d%% durability."] = "Aún no hay nada que reparar. %s es lo más gastado, al %d%% de durabilidad.",
	["Nothing needs your attention right now. Trailhead will speak up when something does."] = "Ahora mismo nada necesita tu atención. Trailhead avisará cuando algo lo necesite.",
	["Nothing to sell right now."] = "Nada que vender ahora mismo.",
	["Nothing to set here"] = "Nada que ajustar aquí",
	["Nothing urgent"] = "Nada urgente",
	["Nothing you wear can break"] = "Nada de lo que llevas puede romperse",
	["Nothing you wear has a durability yet, so there is nothing to repair."] = "Nada de lo que llevas tiene durabilidad aún, así que no hay nada que reparar.",
	["Nothing your abilities use up"] = "Nada que gasten tus facultades",
	["Now"] = "Ya",
	["Off"] = "No",
	["Often skipped. He is immune to nature damage and hits hard. Keep the one in front healed."] = "Muchos se lo saltan. Es inmune al daño de naturaleza y pega fuerte. Mantén sanado al que va delante.",
	["On"] = "Sí",
	["On Alcaz Island, off the shore of Dustwallow Marsh. The entrance is in the basement of the large building."] = "En la Isla de Alcaz, frente a la costa del Marjal Revolcafango. La entrada está en el sótano del gran edificio.",
	["On Caer Darrow, the island in the Western Plaguelands. The door to the portal needs the Skeleton Key, from a long quest chain."] = "En Castel Darrow, la isla de las Tierras de la Peste del Oeste. La puerta del portal necesita la Llave esqueleto, de una larga cadena de misiones.",
	["On a hill over Marshal's Refuge in Un'Goro Crater."] = "En una colina sobre el Refugio de Marshal, en el Cráter de Un'Goro.",
	["On a pile of bones, among skeletons."] = "Sobre un montón de huesos, entre esqueletos.",
	["On an island in the lake."] = "En una isla del lago.",
	["On the PvE ruleset you fight other players only when you choose (type /pvp). On the PvP ruleset you can be attacked almost anywhere. Dying to a player does not wear your gear."] = "En el modo JcE solo luchas contra otros jugadores cuando tú eliges (escribe /pvp). En el modo JcJ pueden atacarte casi en cualquier sitio. Morir a manos de un jugador no desgasta tu equipo.",
	["On the central bridge of Shadowforge City."] = "En el puente central de la Ciudad Forjatiniebla.",
	["On the high ledge in the gardens."] = "En la cornisa alta de los jardines.",
	["On the middle platform of the big cave."] = "En la plataforma central de la gran cueva.",
	["On the pirate ship, on the main deck."] = "En el barco pirata, en la cubierta principal.",
	["On the platform at the top of the Launch Bay."] = "En la plataforma de lo alto de la Launch Bay.",
	["On the platform at the very bottom."] = "En la plataforma de lo más hondo.",
	["On the streets of the Living part."] = "En las calles de la parte Viva.",
	["On the throne at the back of the keep. He is the last boss."] = "En el trono al fondo del torreón. Es el último jefe.",
	["On the throne in the Imperial Seat. He is the last boss."] = "En el trono del Imperial Seat. Es el último jefe.",
	["On the way to level %d, with %d%% of a level rested."] = "De camino al nivel %d, con un %d%% de nivel en descanso.",
	["Once one player opens the West or North door, a torch just inside lets the others in."] = "Cuando un jugador abre la puerta Oeste o Norte, una antorcha justo dentro deja pasar a los demás.",
	["Once there, fly to %s"] = "Una vez allí, vuela a %s",
	["Once they are open, the raids you are saved to show here."] = "Cuando estén abiertas, aquí aparecen las bandas en las que tienes registro.",
	["One at a time"] = "De uno en uno",
	["One click on a defeated enemy picks up everything, so you never miss loot."] = "Un clic en un enemigo derrotado lo recoge todo, así que nunca te dejas botín.",
	["One doorway leads into two dungeons: Lower Blackrock Spire for five players and Upper Blackrock Spire for ten. Levels 55 and up. Lower is the best first target."] = "Una sola entrada lleva a dos mazmorras: la Cumbre de Roca Negra Inferior para cinco jugadores y la Superior para diez. Niveles 55 y más. La Inferior es el mejor primer objetivo.",
	["One of four trolls appears. Kill it and its friends."] = "Aparece uno de cuatro trols. Mátalo a él y a sus amigos.",
	["One of the Mana Elemental and Mana Wraith is the boss in the Path of Renewal. It is not clear which."] = "El jefe del Path of Renewal es el Elemental de maná o el Ánima de maná. No está claro cuál.",
	["One of the first bosses inside."] = "Uno de los primeros jefes de dentro.",
	["One pet with you and two more at a stable master."] = "Una mascota contigo y dos más con un maestro de establos.",
	["Only appears after you use the item. Ask your group."] = "Solo aparece tras usar el objeto. Pregunta a tu grupo.",
	["Only appears for a warlock quest."] = "Solo aparece para una misión de brujo.",
	["Only fight him if the group is ready for the whole bar."] = "Lucha contra él solo si el grupo está listo para todo el bar.",
	["Only go for him if the whole group is happy to swim. Watch your breath."] = "Ve a por él solo si todo el grupo está dispuesto a nadar. Vigila tu respiración.",
	["Only in the 20-player version, in Jammal'an's room."] = "Solo en la versión de 20 jugadores, en la sala de Jammal'an.",
	["Only in the 20-player version. Where it stands is not known."] = "Solo en la versión de 20 jugadores. No se sabe dónde está.",
	["Only in the 20-player version. Where they stand is not known."] = "Solo en la versión de 20 jugadores. No se sabe dónde están.",
	["Only in the 20-player version: the two dragons as one fight."] = "Solo en la versión de 20 jugadores: los dos dragones en un solo combate.",
	["Only needed for quests."] = "Solo hace falta para misiones.",
	["Onyxia's Lair"] = "Guarida de Onyxia",
