	["Your critical strikes hit harder."] = "Tus golpes críticos pegan más fuerte.",
	["Your critical strikes make the enemy bleed."] = "Tus golpes críticos hacen sangrar al enemigo.",
	["Your critical strikes with ranged attacks hit much harder."] = "Tus golpes críticos con ataques a distancia pegan mucho más fuerte.",
	["Your demon does more damage."] = "Tu demonio hace más daño.",
